window.__IN_I18N={"Meridyen Yapı · 1986'dan beri":{"en":"Meridyen Yapı · Since 1986","ru":"Meridyen Yapı · с 1986 года","zh":"Meridyen Yapı · 自1986年","ar":"Meridyen Yapı · منذ 1986"},"Hizmetlerimiz":{"en":"Our Services","ru":"Наши услуги","zh":"我们的服务","ar":"خدماتنا"},"Kurumsal İnşaat Hizmetlerimiz":{"en":"Our Corporate <span class=\"mk\">Construction Services</span>","ru":"Наши корпоративные строительные услуги","zh":"我们的企业级建筑服务","ar":"خدماتنا الإنشائية المؤسسية"},"Arsanın imar analizinden anahtar teslimine kadar; konut, kentsel dönüşüm, kat karşılığı, tadilat, güçlendirme ve ticari yapıları tek çatı altında üretiyoruz. Her proje TBDY 2018 deprem yönetmeliğine uyumlu, bağımsız yapı denetimli ve sözleşmeye bağlı sabit fiyat & sabit takvim güvencesiyle yürütülür.":{"en":"From the zoning analysis of the plot to turnkey handover, we deliver residential, urban-renewal, land-for-flat, renovation, retrofitting and commercial buildings under one roof. Every project complies with the TBDY 2018 seismic code, is independently inspected and is carried out with a contractual fixed-price & fixed-schedule guarantee.","ru":"От анализа зонирования участка до сдачи «под ключ» мы возводим жильё, объекты городской реновации, строительство в обмен на квартиры, ремонт, усиление и коммерческие здания под одной крышей. Каждый проект соответствует сейсмическим нормам TBDY 2018, проходит независимый строительный надзор и реализуется с договорной гарантией фиксированной цены и фиксированного графика.","zh":"从地块的规划分析到交钥匙交付，我们在同一屋檐下承建住宅、城市更新、以房换地、翻新、加固及商业建筑。每个项目均符合 TBDY 2018 抗震规范，接受独立建筑监理，并以合同约定的固定价格与固定工期作为保障。","ar":"من تحليل التنظيم العمراني للأرض حتى التسليم المفتاح، ننجز تحت سقف واحد المباني السكنية ومشاريع التحول الحضري والإنشاء مقابل حصص شقق والتجديد والتقوية والمباني التجارية. يلتزم كل مشروع بكود الزلازل TBDY 2018، ويخضع لتدقيق إنشائي مستقل، ويُنفَّذ بضمان تعاقدي بسعر ثابت وجدول زمني ثابت."},"Nasıl Çalışıyoruz?":{"en":"How We Work","ru":"Как мы работаем?","zh":"我们如何工作？","ar":"كيف نعمل؟"},"yıl kurumsal deneyim":{"en":"years of corporate experience","ru":"лет корпоративного опыта","zh":"年企业经验","ar":"عامًا من الخبرة المؤسسية"},"8.400+":{"en":"8,400+","ru":"8.400+","zh":"8.400+","ar":"8.400+"},"teslim edilen bağımsız bölüm":{"en":"independent units delivered","ru":"сданных самостоятельных помещений","zh":"已交付独立单元","ar":"وحدة مستقلة مُسلَّمة"},"%100":{"en":"100%","ru":"100%","zh":"100%","ar":"100%"},"TBDY 2018 uyumu":{"en":"TBDY 2018 compliance","ru":"Соответствие TBDY 2018","zh":"符合 TBDY 2018","ar":"التزام بـ TBDY 2018"},"uzmanlaşmış hizmet alanı":{"en":"specialised service areas","ru":"специализированных направлений услуг","zh":"个专业服务领域","ar":"مجال خدمة متخصص"},"Konut İnşaatı":{"en":"Residential Construction","ru":"Жилищное строительство","zh":"住宅建筑","ar":"الإنشاء السكني"},"Anahtar Teslim":{"en":"Turnkey Contracting","ru":"Строительство «под ключ»","zh":"交钥匙承建","ar":"التعهد بالتسليم المفتاح"},"Kentsel Dönüşüm":{"en":"Urban Renewal","ru":"Городская реновация","zh":"城市更新","ar":"التحول الحضري"},"Kat Karşılığı":{"en":"Land-for-Flat","ru":"Строительство в обмен на квартиры","zh":"以房换地","ar":"الإنشاء مقابل حصص شقق"},"Tadilat & Renovasyon":{"en":"Renovation & Refurbishment","ru":"Ремонт и реновация","zh":"翻新与改造","ar":"التجديد والتحديث"},"Güçlendirme & Restorasyon":{"en":"Retrofitting & Restoration","ru":"Усиление и реставрация","zh":"加固与修复","ar":"التقوية والترميم"},"Ticari & Karma Yapılar":{"en":"Commercial & Mixed-Use Buildings","ru":"Коммерческие и многофункциональные здания","zh":"商业与综合体建筑","ar":"المباني التجارية والمختلطة الاستخدام"},"Endüstriyel Yapılar":{"en":"Industrial Buildings","ru":"Промышленные здания","zh":"工业建筑","ar":"المباني الصناعية"},"Kapsam":{"en":"Scope","ru":"Объём","zh":"范围","ar":"النطاق"},"Süreç":{"en":"Process","ru":"Процесс","zh":"流程","ar":"المسار"},"Konut İnşaatı — Anahtar Teslim Rezidans & Site":{"en":"Residential Construction — Turnkey Residences & Complexes","ru":"Жилищное строительство — резиденции и жилые комплексы «под ключ»","zh":"住宅建筑 — 交钥匙住宅与社区","ar":"الإنشاء السكني — مبانٍ سكنية ومجمعات بالتسليم المفتاح"},"Lüks rezidans, apartman ve site projelerinde arsa analizinden anahtar teslime kadar tüm konut üretim sürecini tek çatı altında yönetiyoruz.":{"en":"We manage the entire residential production process under one roof — from plot analysis to turnkey handover — for luxury residences, apartment buildings and gated complexes.","ru":"В проектах элитных резиденций, жилых домов и комплексов мы управляем всем процессом жилищного строительства под одной крышей — от анализа участка до сдачи «под ключ».","zh":"在豪华住宅、公寓与封闭式社区项目中，我们在同一屋檐下管理从地块分析到交钥匙交付的整个住宅建造流程。","ar":"في مشاريع المساكن الفاخرة والعمارات والمجمعات السكنية، ندير كامل عملية الإنتاج السكني تحت سقف واحد — من تحليل الأرض حتى التسليم المفتاح."},"Kalıcı değeri belirleyen ilk karar zeminde alınır: yerinde açılan jeoteknik sondajlarla zemin sınıfı ve emniyet gerilmesi belirlenir, buna göre radye ya da kazıklı temel seçilir. Taşıyıcı sistem, TBDY 2018'in öngördüğü deprem tasarım sınıfına (DTS) ve bina yükseklik sınıfına (BYS) uygun olarak C30/37 betonu ve nervürlü donatıyla süneklik hedefiyle boyutlandırılır. Üretimde BIM ile mimari, statik ve MEP disiplinleri tek modelde çakıştırılır; clash detection sayesinde sahada maliyet doğuran çakışmalar tasarım masasında çözülür. A sınıfı enerji performansı ve her etabın bağımsız yapı denetimiyle belgelenmesi standardımızdır.":{"en":"The first decision that defines lasting value is made in the ground: on-site geotechnical boreholes determine the soil class and bearing capacity, and a raft or piled foundation is chosen accordingly. The structural system is designed for ductility with C30/37 concrete and ribbed reinforcement, in line with the seismic design class (DTS) and building height class (BYS) required by TBDY 2018. In production, the architectural, structural and MEP disciplines are overlaid in a single BIM model; thanks to clash detection, conflicts that would cost money on site are resolved at the design desk. Class-A energy performance and documentation of every stage through independent building inspection are our standard.","ru":"Первое решение, определяющее долговременную ценность, принимается в грунте: пробуренные на месте геотехнические скважины определяют класс грунта и несущую способность, и в соответствии с этим выбирается плитный или свайный фундамент. Несущая система рассчитывается на пластичность с применением бетона C30/37 и рёбристой арматуры в соответствии с классом сейсмического проектирования (DTS) и классом высотности здания (BYS), предусмотренными TBDY 2018. В производстве архитектурная, конструктивная и инженерная (MEP) дисциплины совмещаются в единой BIM-модели; благодаря clash detection коллизии, которые обошлись бы дорого на стройплощадке, устраняются ещё за проектным столом. Энергоэффективность класса A и документирование каждого этапа через независимый строительный надзор — наш стандарт.","zh":"决定长久价值的第一个决策在地基中作出：现场钻探的地质勘察孔确定土壤类别与承载力，并据此选择筏板基础或桩基础。承重体系按照 TBDY 2018 规定的抗震设计等级（DTS）与建筑高度等级（BYS），采用 C30/37 混凝土与带肋钢筋，以延性为目标进行设计。在建造中，建筑、结构与机电（MEP）专业在单一 BIM 模型中叠合；借助 clash detection，本会在工地上造成成本的冲突在设计阶段即被解决。A 级能效以及通过独立建筑监理对每个阶段进行记录，是我们的标准。","ar":"القرار الأول الذي يحدد القيمة الدائمة يُتخذ في التربة: تحدد جسّات المسح الجيوتقني المحفورة في الموقع صنف التربة وقدرة التحمل، ويُختار وفقًا لذلك أساس لبشة أو أساس خوازيق. يُصمَّم النظام الإنشائي بهدف المطاوعة باستخدام خرسانة C30/37 وحديد تسليح مضلّع، بما يتوافق مع صنف التصميم الزلزالي (DTS) وصنف ارتفاع المبنى (BYS) المنصوص عليهما في TBDY 2018. في التنفيذ، تُدمج تخصصات العمارة والإنشاء والميكانيكا/الكهرباء (MEP) في نموذج BIM واحد؛ وبفضل clash detection تُحل في مرحلة التصميم التعارضات التي كانت ستكلّف مالًا في الموقع. أداء الطاقة من الصنف A وتوثيق كل مرحلة عبر التدقيق الإنشائي المستقل هما معيارنا."},"Zemin etüdü & jeoteknik rapor":{"en":"Soil survey & geotechnical report","ru":"Изыскания грунта и геотехнический отчёт","zh":"地质勘察与岩土报告","ar":"مسح التربة والتقرير الجيوتقني"},"Mimari + statik + mekanik + elektrik proje":{"en":"Architectural + structural + mechanical + electrical design","ru":"Архитектурный + конструктивный + механический + электрический проект","zh":"建筑 + 结构 + 机械 + 电气设计","ar":"تصميم معماري + إنشائي + ميكانيكي + كهربائي"},"Betonarme C30/37 taşıyıcı sistem":{"en":"C30/37 reinforced-concrete structural system","ru":"Железобетонная несущая система C30/37","zh":"C30/37 钢筋混凝土承重体系","ar":"نظام إنشائي من الخرسانة المسلحة C30/37"},"BIM koordinasyonu & clash detection":{"en":"BIM coordination & clash detection","ru":"BIM-координация и clash detection","zh":"BIM 协调与 clash detection","ar":"تنسيق BIM و clash detection"},"A sınıfı enerji & akıllı bina altyapısı":{"en":"Class-A energy & smart-building infrastructure","ru":"Энергоэффективность класса A и инфраструктура «умного дома»","zh":"A 级能效与智能建筑基础设施","ar":"طاقة من الصنف A وبنية تحتية للمبنى الذكي"},"İskân belgesi & anahtar teslim":{"en":"Occupancy permit & turnkey handover","ru":"Разрешение на ввод в эксплуатацию и сдача «под ключ»","zh":"房屋使用许可与交钥匙交付","ar":"رخصة الإشغال والتسليم المفتاح"},"Arsa & İmar Analizi":{"en":"Plot & Zoning Analysis","ru":"Анализ участка и зонирования","zh":"地块与规划分析","ar":"تحليل الأرض والتنظيم العمراني"},"TAKS/KAKS/Hmax hesabı, inşaat hakkı ve kısıtların tespiti":{"en":"TAKS/KAKS/Hmax calculation, building rights and constraints assessment","ru":"Расчёт TAKS/KAKS/Hmax, определение прав застройки и ограничений","zh":"TAKS/KAKS/Hmax 计算、建筑权利与限制评估","ar":"حساب TAKS/KAKS/Hmax وتحديد حقوق البناء والقيود"},"Zemin Etüdü & Fizibilite":{"en":"Soil Survey & Feasibility","ru":"Изыскания грунта и ТЭО","zh":"地质勘察与可行性","ar":"مسح التربة ودراسة الجدوى"},"Jeoteknik sondaj, zemin sınıfı ve gider-gelir fizibilitesi":{"en":"Geotechnical boreholes, soil class and cost-revenue feasibility","ru":"Геотехническое бурение, класс грунта и технико-экономическое обоснование расходов и доходов","zh":"地质钻探、土壤类别与收支可行性","ar":"الجسّات الجيوتقنية وصنف التربة ودراسة جدوى النفقات والإيرادات"},"Proje & Ruhsat":{"en":"Design & Permit","ru":"Проект и разрешение","zh":"设计与许可","ar":"التصميم والرخصة"},"Mimari, statik, mekanik, elektrik projeleri ve yapı ruhsatı":{"en":"Architectural, structural, mechanical, electrical designs and the building permit","ru":"Архитектурный, конструктивный, механический, электрический проекты и разрешение на строительство","zh":"建筑、结构、机械、电气设计与建筑许可","ar":"التصاميم المعمارية والإنشائية والميكانيكية والكهربائية ورخصة البناء"},"Temel & Kaba Yapı":{"en":"Foundation & Shell","ru":"Фундамент и черновой каркас","zh":"基础与主体结构","ar":"الأساس والهيكل الخرساني"},"Hafriyat-iksa, radye/kazıklı temel, betonarme karkas":{"en":"Excavation-shoring, raft/piled foundation, reinforced-concrete frame","ru":"Земляные работы-крепление котлована, плитный/свайный фундамент, железобетонный каркас","zh":"土方-基坑支护、筏板/桩基础、钢筋混凝土框架","ar":"الحفر وإسناد الحفريات، أساس اللبشة/الخوازيق، الهيكل الخرساني المسلح"},"İnce İşler & İskân":{"en":"Finishing & Occupancy","ru":"Чистовые работы и ввод в эксплуатацию","zh":"精装工程与房屋使用许可","ar":"أعمال التشطيب والإشغال"},"Sıva-boya-kaplama, enerji kimlik belgesi, anahtar teslim":{"en":"Plaster-paint-cladding, energy performance certificate, turnkey handover","ru":"Штукатурка-покраска-облицовка, энергетический паспорт, сдача «под ключ»","zh":"抹灰-涂料-饰面、能源身份证书、交钥匙交付","ar":"اللياسة والدهان والتكسية، شهادة هوية الطاقة، التسليم المفتاح"},"İmar Kanunu 3194":{"en":"Zoning Law 3194","ru":"Закон о зонировании 3194","zh":"规划法 3194","ar":"قانون التنظيم العمراني 3194"},"Yapı Denetim 4708":{"en":"Building Inspection 4708","ru":"Строительный надзор 4708","zh":"建筑监理 4708","ar":"التدقيق الإنشائي 4708"},"BEP-TR Enerji":{"en":"BEP-TR Energy","ru":"BEP-TR Энергия","zh":"BEP-TR 能源","ar":"طاقة BEP-TR"},"Konut projeniz için keşif →":{"en":"Survey for your residential project →","ru":"Выезд для вашего жилищного проекта →","zh":"为您的住宅项目预约勘察 →","ar":"معاينة لمشروعك السكني →"},"C30/37 betonarme":{"en":"C30/37 reinforced concrete","ru":"Железобетон C30/37","zh":"C30/37 钢筋混凝土","ar":"خرسانة مسلحة C30/37"},"A sınıfı enerji":{"en":"Class-A energy","ru":"Энергоэффективность класса A","zh":"A 级能效","ar":"طاقة من الصنف A"},"Anahtar Teslim Taahhüt (EPC)":{"en":"Turnkey Contracting (EPC)","ru":"Подряд «под ключ» (EPC)","zh":"交钥匙承包（EPC）","ar":"التعهد بالتسليم المفتاح (EPC)"},"Mühendislikten tasarıma, tedarikten iskâna kadar tüm sorumluluğun tek yüklenicide toplandığı EPC (Engineering-Procurement-Construction) modeli.":{"en":"An EPC (Engineering-Procurement-Construction) model in which all responsibility — from engineering to design, procurement to occupancy — is consolidated in a single contractor.","ru":"Модель EPC (Engineering-Procurement-Construction), в которой вся ответственность — от инжиниринга до проектирования, от поставок до ввода в эксплуатацию — сосредоточена у единственного подрядчика.","zh":"一种 EPC（Engineering-Procurement-Construction，设计-采购-施工）模式，将从工程到设计、从采购到房屋使用许可的全部责任集中于单一承包商。","ar":"نموذج EPC (Engineering-Procurement-Construction) الذي تتركّز فيه كامل المسؤولية — من الهندسة إلى التصميم، ومن التوريد إلى الإشغال — لدى مقاول واحد."},"Anahtar teslim (götürü bedel) modelinde kapsam, maliyet ve süre riski işverenden yükleniciye geçer: sabit fiyat verildiği için keşif ve tasarım hataları bizim sorumluluğumuzdadır. Bu yüzden işi sağlam bir ön proje ve BIM koordinasyonuyla başlatır, disiplinler arası çakışmaları sözleşme öncesi çözerek fiyatı gerçekçi ve sürdürülebilir kılarız. İşverenin kazancı öngörülebilirliktir: tek sözleşme, tek muhatap, sabit takvim ve kademeli hakediş. Kalite ve iş güvenliği (6331) yönetimi standarttır; teslim geçici kabulle başlar, garanti süresi sonunda kesin kabulle tamamlanır.":{"en":"In the turnkey (lump-sum) model, the scope, cost and schedule risk shifts from the client to the contractor: because a fixed price is given, survey and design errors are our responsibility. That is why we start the work with a solid preliminary design and BIM coordination, resolving inter-disciplinary clashes before the contract to keep the price realistic and sustainable. The client's gain is predictability: a single contract, a single point of contact, a fixed schedule and staged progress payments. Quality and occupational-safety (6331) management are standard; delivery begins with provisional acceptance and is completed with final acceptance at the end of the warranty period.","ru":"В модели «под ключ» (твёрдая договорная цена) риск объёма, стоимости и сроков переходит от заказчика к подрядчику: поскольку цена фиксированная, ошибки изысканий и проектирования — наша ответственность. Поэтому мы начинаем работу с надёжного эскизного проекта и BIM-координации, устраняя междисциплинарные коллизии ещё до заключения договора, чтобы цена была реалистичной и устойчивой. Выгода заказчика — предсказуемость: единый договор, единое контактное лицо, фиксированный график и поэтапные платежи по факту выполнения. Управление качеством и охраной труда (6331) — стандарт; сдача начинается с предварительной приёмки и завершается окончательной приёмкой по истечении гарантийного срока.","zh":"在交钥匙（总价包干）模式中，范围、成本与工期风险由业主转移至承包商：由于给出固定价格，勘察与设计失误由我们承担。因此我们以扎实的初步设计与 BIM 协调开始工作，在签约前解决专业间冲突，使价格切合实际且可持续。业主的收益是可预见性：单一合同、单一对接人、固定工期与分阶段进度款。质量与职业安全（6331）管理是标准配置；交付以初步验收开始，在质保期结束时以最终验收完成。","ar":"في نموذج التسليم المفتاح (السعر الإجمالي المقطوع) تنتقل مخاطر النطاق والتكلفة والمدة من صاحب العمل إلى المقاول: فلأن السعر ثابت، تقع أخطاء المعاينة والتصميم على مسؤوليتنا. لذلك نبدأ العمل بتصميم أولي متين وتنسيق BIM، حالّين التعارضات بين التخصصات قبل التعاقد كي يبقى السعر واقعيًا ومستدامًا. مكسب صاحب العمل هو قابلية التنبؤ: عقد واحد، جهة تواصل واحدة، جدول زمني ثابت ودفعات مرحلية بحسب الإنجاز. إدارة الجودة والسلامة المهنية (6331) معيار ثابت؛ يبدأ التسليم بالاستلام المؤقت ويكتمل بالاستلام النهائي عند انتهاء فترة الضمان."},"Tek elden proje yönetimi (EPC)":{"en":"Single-source project management (EPC)","ru":"Управление проектом из одних рук (EPC)","zh":"一站式项目管理（EPC）","ar":"إدارة المشروع من جهة واحدة (EPC)"},"Sabit götürü bedel & sabit takvim":{"en":"Fixed lump-sum price & fixed schedule","ru":"Фиксированная твёрдая цена и фиксированный график","zh":"固定总价包干与固定工期","ar":"سعر إجمالي مقطوع ثابت وجدول زمني ثابت"},"Tüm disiplinlerin koordinasyonu":{"en":"Coordination of all disciplines","ru":"Координация всех дисциплин","zh":"所有专业的协调","ar":"تنسيق جميع التخصصات"},"Hakediş & maliyet kontrolü":{"en":"Progress payments & cost control","ru":"Платежи по факту выполнения и контроль затрат","zh":"进度款与成本控制","ar":"الدفعات المرحلية وضبط التكاليف"},"Kalite & İSG (6331) yönetimi":{"en":"Quality & OHS (6331) management","ru":"Управление качеством и охраной труда (6331)","zh":"质量与职业健康安全（6331）管理","ar":"إدارة الجودة والسلامة المهنية (6331)"},"Garanti & satış sonrası":{"en":"Warranty & after-sales","ru":"Гарантия и постпродажное обслуживание","zh":"质保与售后","ar":"الضمان وخدمات ما بعد البيع"},"Sözleşme":{"en":"Contract","ru":"Договор","zh":"合同","ar":"العقد"},"Kapsam, götürü bedel ve takvim mutabakatı":{"en":"Agreement on scope, lump-sum price and schedule","ru":"Согласование объёма, твёрдой цены и графика","zh":"就范围、总价包干与工期达成一致","ar":"الاتفاق على النطاق والسعر المقطوع والجدول الزمني"},"Planlama":{"en":"Planning","ru":"Планирование","zh":"规划","ar":"التخطيط"},"CPM kritik yol ve kaynak planı, BIM koordinasyonu":{"en":"CPM critical-path and resource plan, BIM coordination","ru":"План критического пути CPM и ресурсов, BIM-координация","zh":"CPM 关键路径与资源计划、BIM 协调","ar":"مخطط المسار الحرج CPM والموارد، وتنسيق BIM"},"Tedarik":{"en":"Procurement","ru":"Поставки","zh":"采购","ar":"التوريد"},"Malzeme, ekipman ve işgücünün önceden bağlanması":{"en":"Advance commitment of materials, equipment and labour","ru":"Заблаговременное закрепление материалов, оборудования и рабочей силы","zh":"材料、设备与劳动力的提前锁定","ar":"الحجز المسبق للمواد والمعدات والعمالة"},"Üretim":{"en":"Production","ru":"Производство","zh":"生产","ar":"التنفيذ"},"Hakediş sistemiyle kontrollü, denetimli inşaat":{"en":"Controlled, inspected construction with a progress-payment system","ru":"Контролируемое, поднадзорное строительство с системой платежей по факту выполнения","zh":"以进度款制度进行的受控、受监理施工","ar":"إنشاء مضبوط ومُدقَّق بنظام الدفعات المرحلية"},"Test & Teslim":{"en":"Testing & Handover","ru":"Испытания и сдача","zh":"测试与交付","ar":"الاختبار والتسليم"},"Devreye alma, geçici-kesin kabul ve anahtar teslim":{"en":"Commissioning, provisional-final acceptance and turnkey handover","ru":"Пусконаладка, предварительная-окончательная приёмка и сдача «под ключ»","zh":"调试、初步-最终验收与交钥匙交付","ar":"التشغيل التجريبي، الاستلام المؤقت-النهائي والتسليم المفتاح"},"Sabit fiyatlı teklif alın →":{"en":"Get a fixed-price quote →","ru":"Получить предложение с фиксированной ценой →","zh":"获取固定价格报价 →","ar":"احصل على عرض بسعر ثابت →"},"Sabit fiyat":{"en":"Fixed price","ru":"Фиксированная цена","zh":"固定价格","ar":"سعر ثابت"},"Tek muhatap":{"en":"Single point of contact","ru":"Единое контактное лицо","zh":"单一对接人","ar":"جهة تواصل واحدة"},"Kentsel Dönüşüm — 6306 Sayılı Kanun":{"en":"Urban Renewal — Law No. 6306","ru":"Городская реновация — Закон № 6306","zh":"城市更新 — 第 6306 号法律","ar":"التحول الحضري — القانون رقم 6306"},"Riskli yapıların 6306 sayılı kanun kapsamında güvenli yenilenmesini, hak sahiplerinin haklarını koruyarak uçtan uca yönetiyoruz.":{"en":"We manage the safe renewal of risky buildings end-to-end under Law No. 6306, protecting the rights of the beneficiaries throughout.","ru":"Мы управляем безопасным обновлением рискованных зданий от начала до конца в рамках Закона № 6306, защищая права правообладателей на всех этапах.","zh":"我们在第 6306 号法律框架下端到端管理风险建筑的安全更新，并全程保护权利人的权益。","ar":"ندير من البداية إلى النهاية التجديد الآمن للمباني الخطرة في إطار القانون رقم 6306، مع حماية حقوق أصحاب الحقوق طوال المسار."},"Sürecin yasal omurgası 6306 sayılı kanundur. Bakanlıkça lisanslandırılmış kuruluşun hazırladığı riskli yapı raporuyla başlar; rapor onaylanınca tapuya \"riskli yapı\" şerhi işlenir, maliklere e-Devlet üzerinden tebliğ edilir ve 15 günlük itiraz hakkı tanınır. Dönüşüm kararı arsa payının en az 2/3 çoğunluğuyla alınır; katılmayan maliklerin payları bağımsız (SPK lisanslı) değerleme rayici üzerinden açık artırmayla değerlendirilir. 2023 değişikliğiyle kira yardımı başvuru süresi bir yıla çıkarılmıştır. Güçlendirme mi, yıkıp yeniden yapmak mı sorusu yalnızca maliyetle değil imar haklarıyla da ilgilidir; iki senaryoyu bağımsız mühendis raporuyla karşılaştırmalı sunarız.":{"en":"The legal backbone of the process is Law No. 6306. It begins with a risky-building report prepared by a ministry-licensed body; once the report is approved, a \"risky building\" annotation is registered on the title deed, owners are notified via e-Government and a 15-day right to object is granted. The renewal decision is taken by at least a two-thirds majority of the land share; the shares of non-participating owners are valued and sold by auction at the appraised market rate of an independent (CMB-licensed) valuer. With the 2023 amendment, the rent-assistance application period was extended to one year. Whether to retrofit or demolish and rebuild depends not only on cost but also on zoning rights; we present the two scenarios comparatively with an independent engineer's report.","ru":"Правовая основа процесса — Закон № 6306. Он начинается с отчёта о рискованном здании, подготовленного лицензированной министерством организацией; после утверждения отчёта в свидетельство о собственности вносится отметка «рискованное здание», собственники уведомляются через e-Devlet, и им предоставляется 15-дневное право на возражение. Решение о реновации принимается большинством не менее 2/3 долей земельного участка; доли не участвующих собственников оцениваются и реализуются с аукциона по рыночной стоимости, определённой независимым (лицензированным SPK) оценщиком. С поправкой 2023 года срок подачи заявления на арендную помощь продлён до одного года. Вопрос — усиливать или сносить и строить заново — зависит не только от стоимости, но и от прав застройки; мы представляем оба сценария сравнительно, с отчётом независимого инженера.","zh":"该流程的法律主干是第 6306 号法律。它始于由部级授权机构编制的风险建筑报告；报告获批后，产权证上登记「风险建筑」批注，业主通过 e-Devlet 收到通知，并享有 15 天的异议权。更新决定须由地块份额至少 2/3 的多数作出；未参与业主的份额按独立（SPK 持牌）估价机构评定的市场行情通过拍卖处置。2023 年修订将租金补助的申请期限延长至一年。是加固还是拆除重建，不仅取决于成本，也取决于建筑权利；我们以独立工程师报告对两种方案进行对比呈现。","ar":"العمود الفقري القانوني للمسار هو القانون رقم 6306. يبدأ بتقرير مبنى خطر تُعدّه جهة مرخّصة من الوزارة؛ وبعد اعتماد التقرير يُدوَّن على صحيفة الملكية شرح «مبنى خطر»، ويُبلَّغ المُلّاك عبر e-Devlet مع منحهم حق اعتراض مدته 15 يومًا. يُتَّخذ قرار التحول بأغلبية لا تقل عن ثلثي حصص الأرض؛ أما حصص المُلّاك غير المشاركين فتُقيَّم وتُباع بالمزاد وفق القيمة السوقية التي تحددها جهة تقييم مستقلة (مرخّصة من SPK). وبتعديل 2023 مُدِّدت مهلة تقديم طلب مساعدة الإيجار إلى سنة واحدة. ومسألة التقوية أم الهدم وإعادة البناء لا تتعلق بالتكلفة وحدها بل بحقوق البناء أيضًا؛ ونعرض السيناريوهين على نحو مقارن بتقرير مهندس مستقل."},"Riskli yapı tespiti & rapor":{"en":"Risky-building assessment & report","ru":"Определение рискованного здания и отчёт","zh":"风险建筑鉴定与报告","ar":"تحديد المبنى الخطر والتقرير"},"6306 yasal süreç yönetimi":{"en":"6306 legal-process management","ru":"Управление юридическим процессом 6306","zh":"6306 法律流程管理","ar":"إدارة المسار القانوني 6306"},"Hak sahibi sözleşmeleri & mutabakat":{"en":"Beneficiary agreements & consensus","ru":"Договоры с правообладателями и достижение согласия","zh":"权利人合同与共识","ar":"عقود أصحاب الحقوق والتوافق"},"Kira yardımı & taşınma desteği":{"en":"Rent assistance & relocation support","ru":"Арендная помощь и поддержка переезда","zh":"租金补助与搬迁支持","ar":"مساعدة الإيجار ودعم الانتقال"},"TBDY 2018 uyumlu güçlü yeni yapı":{"en":"A strong new TBDY 2018-compliant building","ru":"Прочное новое здание, соответствующее TBDY 2018","zh":"符合 TBDY 2018 的坚固新建筑","ar":"مبنى جديد متين متوافق مع TBDY 2018"},"Sosyal donatı & otopark":{"en":"Social amenities & parking","ru":"Социальная инфраструктура и парковка","zh":"社区配套与停车","ar":"المرافق الاجتماعية ومواقف السيارات"},"Riskli Yapı Tespiti":{"en":"Risky-Building Assessment","ru":"Определение рискованного здания","zh":"风险建筑鉴定","ar":"تحديد المبنى الخطر"},"Bakanlık lisanslı kuruluşça karot ve performans analizi":{"en":"Core sampling and performance analysis by a ministry-licensed body","ru":"Отбор кернов и анализ характеристик лицензированной министерством организацией","zh":"由部级授权机构进行取芯与性能分析","ar":"أخذ العينات اللبّية وتحليل الأداء بواسطة جهة مرخّصة من الوزارة"},"Şerh & Tebligat":{"en":"Annotation & Notification","ru":"Отметка и уведомление","zh":"批注与送达","ar":"الشرح والتبليغ"},"Tapuya riskli yapı şerhi, maliklere e-Devlet tebliği (15 gün itiraz)":{"en":"Risky-building annotation on the deed, e-Government notification to owners (15-day objection)","ru":"Отметка о рискованном здании в свидетельстве, уведомление собственников через e-Devlet (15 дней на возражение)","zh":"产权证上的风险建筑批注、通过 e-Devlet 向业主送达（15 天异议期）","ar":"شرح المبنى الخطر على صحيفة الملكية، والتبليغ للمُلّاك عبر e-Devlet (15 يومًا للاعتراض)"},"Malik Mutabakatı":{"en":"Owner Consensus","ru":"Согласие собственников","zh":"业主共识","ar":"توافق المُلّاك"},"Arsa payının 2/3 çoğunluğuyla dönüşüm kararı ve sözleşme":{"en":"Renewal decision and contract by a two-thirds majority of the land share","ru":"Решение о реновации и договор большинством 2/3 долей участка","zh":"以地块份额 2/3 多数作出更新决定与合同","ar":"قرار التحول والعقد بأغلبية ثلثي حصص الأرض"},"Yıkım & Yeni Ruhsat":{"en":"Demolition & New Permit","ru":"Снос и новое разрешение","zh":"拆除与新许可","ar":"الهدم والرخصة الجديدة"},"Tahliye, kira yardımı başvurusu, TBDY 2018 uyumlu proje ve yapı ruhsatı":{"en":"Vacating, rent-assistance application, TBDY 2018-compliant design and building permit","ru":"Выселение, заявление на арендную помощь, проект в соответствии с TBDY 2018 и разрешение на строительство","zh":"腾空、租金补助申请、符合 TBDY 2018 的设计与建筑许可","ar":"الإخلاء، طلب مساعدة الإيجار، تصميم متوافق مع TBDY 2018 ورخصة البناء"},"İnşaat, İskân & Teslim":{"en":"Construction, Occupancy & Handover","ru":"Строительство, ввод в эксплуатацию и сдача","zh":"施工、房屋使用许可与交付","ar":"الإنشاء والإشغال والتسليم"},"Yapı denetimli güçlü bina, iskân ve bağımsız bölüm teslimi":{"en":"Building-inspected strong structure, occupancy permit and unit handover","ru":"Прочное поднадзорное здание, разрешение на ввод и сдача самостоятельных помещений","zh":"受监理的坚固建筑、房屋使用许可与独立单元交付","ar":"مبنى متين مُدقَّق إنشائيًا، رخصة الإشغال وتسليم الوحدات المستقلة"},"6306 Kentsel Dönüşüm":{"en":"6306 Urban Renewal","ru":"Городская реновация 6306","zh":"6306 城市更新","ar":"التحول الحضري 6306"},"Binamın risk durumunu öğren →":{"en":"Check my building's risk status →","ru":"Узнать статус риска моего здания →","zh":"了解我的建筑风险状态 →","ar":"اعرف حالة خطر مبناي →"},"6306 kanun":{"en":"Law 6306","ru":"Закон 6306","zh":"6306 法律","ar":"قانون 6306"},"Kira yardımı":{"en":"Rent assistance","ru":"Арендная помощь","zh":"租金补助","ar":"مساعدة الإيجار"},"Kat Karşılığı İnşaat — Arsa Payı Karşılığı":{"en":"Land-for-Flat Construction — Against a Land Share","ru":"Строительство в обмен на квартиры — в обмен на долю участка","zh":"以房换地建筑 — 以地块份额为对价","ar":"الإنشاء مقابل حصص شقق — مقابل حصة من الأرض"},"Arsa sahipleriyle şeffaf hisse paylaşımına dayalı kazan-kazan projeler. Arsa sahibi hiç para ödemeden arsasını değerlendirir.":{"en":"Win-win projects based on a transparent share split with landowners. The landowner develops the plot without paying anything.","ru":"Взаимовыгодные проекты, основанные на прозрачном разделе долей с владельцами земли. Владелец земли осваивает участок, не платя ничего.","zh":"基于与土地所有者透明份额分配的双赢项目。土地所有者无需支付任何费用即可开发其地块。","ar":"مشاريع رابحة للطرفين قائمة على تقاسم شفاف للحصص مع مالكي الأرض. يستثمر مالك الأرض أرضه دون أن يدفع شيئًا."},"Kat karşılığı inşaat, arsa sahibinin arsasının belirli bir payını yükleniciye devrettiği; yüklenicinin karşılığında ürettiği bağımsız bölümlerin bir kısmını arsa sahibine teslim ettiği, iki tarafa borç yükleyen bir sözleşmedir. Sözleşme yasal geçerlilik için noter huzurunda düzenlenmeli ve tapuya şerh edilmelidir; hangi kat, hangi cephe, kaç metrekare bağımsız bölümün kime ait olduğu net cetvelle yazılır. Güveni somut kılan mekanizma teminattır: yükleniciye devredilen taşınmaza teminat ipoteği konur, buna banka teminat mektubu ve kefalet eklenebilir. Tapu devri genelde inşaat bitmeden yapılmaz, kademeli takvimle ilerler; teslim süresi ve gecikme cezası (TBK cezai şart) sözleşmede açıkça yer alır.":{"en":"Land-for-flat construction is a contract that binds both parties, in which the landowner transfers a certain share of the plot to the contractor and, in return, the contractor delivers part of the units it produces to the landowner. For legal validity, the contract must be executed before a notary and annotated on the title deed; which floor, which façade and how many square metres of which unit belong to whom is set out in a clear schedule. The mechanism that makes trust concrete is security: a security mortgage is placed on the property transferred to the contractor, and a bank letter of guarantee and surety can be added. Title transfer is generally not made before construction is completed and proceeds on a staged schedule; the delivery term and the delay penalty (a penal clause under the Code of Obligations) are stated explicitly in the contract.","ru":"Строительство в обмен на квартиры — это двусторонний договор, по которому владелец земли передаёт подрядчику определённую долю участка, а подрядчик взамен передаёт владельцу часть произведённых им самостоятельных помещений. Для юридической силы договор должен быть оформлен у нотариуса и внесён отметкой в свидетельство о собственности; какой этаж, какой фасад и сколько квадратных метров какого помещения кому принадлежит, прописывается в чёткой ведомости. Механизм, делающий доверие осязаемым, — обеспечение: на переданную подрядчику недвижимость накладывается обеспечительная ипотека, к которой могут добавляться банковская гарантия и поручительство. Передача права собственности, как правило, не производится до завершения строительства и осуществляется по поэтапному графику; срок сдачи и неустойка за просрочку (штрафное условие по Обязательственному кодексу) прямо указываются в договоре.","zh":"以房换地建筑是一份约束双方的合同：土地所有者将地块的一定份额转让给承包商，承包商则将其建成的部分独立单元交付给土地所有者。为具备法律效力，合同须在公证人面前订立并在产权证上批注；哪一层、哪个立面、多少平方米的哪个单元归谁所有，均以清晰的清单写明。使信任具体化的机制是担保：在转让给承包商的不动产上设定担保抵押，并可附加银行保函与保证。产权转让通常在施工完成前不进行，按分阶段计划推进；交付期限与逾期违约金（《债务法》下的违约条款）在合同中明确列明。","ar":"الإنشاء مقابل حصص شقق عقد مُلزِم للطرفين، ينقل بموجبه مالك الأرض حصة معينة من أرضه إلى المقاول، ويسلّم المقاول في المقابل جزءًا من الوحدات المستقلة التي ينتجها إلى مالك الأرض. ولكي يكون العقد نافذًا قانونًا يجب تحريره أمام كاتب العدل وتدوينه شرحًا على صحيفة الملكية؛ ويُكتب في جدول واضح أيّ طابق وأيّ واجهة وكم مترًا مربعًا من أيّ وحدة يعود لمن. والآلية التي تجسّد الثقة هي الضمان: يُرتَّب رهن ضمان على العقار المنقول إلى المقاول، ويمكن أن يُضاف إليه خطاب ضمان بنكي وكفالة. ولا يُجرى نقل الملكية عادةً قبل اكتمال الإنشاء، بل يسير وفق جدول مرحلي؛ وتُذكر مدة التسليم وتعويض التأخير (الشرط الجزائي وفق قانون الالتزامات) صراحةً في العقد."},"Arsa fizibilite & bağımsız değerleme":{"en":"Plot feasibility & independent valuation","ru":"ТЭО участка и независимая оценка","zh":"地块可行性与独立估价","ar":"دراسة جدوى الأرض والتقييم المستقل"},"Adil paylaşım oranı analizi":{"en":"Fair share-ratio analysis","ru":"Анализ справедливой доли распределения","zh":"公平分配比例分析","ar":"تحليل نسبة التقاسم العادلة"},"Noter onaylı, tapuya şerhli sözleşme":{"en":"Notarised contract annotated on the title deed","ru":"Нотариально заверенный договор с отметкой в свидетельстве","zh":"经公证并在产权证上批注的合同","ar":"عقد موثّق لدى كاتب العدل ومُدوَّن شرحًا على صحيفة الملكية"},"Teminat ipoteği & banka teminat mektubu":{"en":"Security mortgage & bank letter of guarantee","ru":"Обеспечительная ипотека и банковская гарантия","zh":"担保抵押与银行保函","ar":"رهن ضمان وخطاب ضمان بنكي"},"Proje, ruhsat & yapım":{"en":"Design, permit & construction","ru":"Проект, разрешение и строительство","zh":"设计、许可与建造","ar":"التصميم والرخصة والبناء"},"Kademeli tapu devri & teslim":{"en":"Staged title transfer & handover","ru":"Поэтапная передача права собственности и сдача","zh":"分阶段产权转让与交付","ar":"نقل ملكية مرحلي وتسليم"},"İmar & Değer Analizi":{"en":"Zoning & Value Analysis","ru":"Анализ зонирования и стоимости","zh":"规划与价值分析","ar":"تحليل التنظيم العمراني والقيمة"},"Arsanın imar hakkı, potansiyeli ve rayiç değeri":{"en":"The plot's zoning rights, potential and market value","ru":"Права застройки, потенциал и рыночная стоимость участка","zh":"地块的建筑权利、潜力与市场价值","ar":"حقوق البناء للأرض وإمكاناتها وقيمتها السوقية"},"Paylaşım Oranı":{"en":"Share Ratio","ru":"Доля распределения","zh":"分配比例","ar":"نسبة التقاسم"},"Adil daire/hasılat paylaşımının belirlenmesi":{"en":"Determining a fair flat/revenue split","ru":"Определение справедливого раздела квартир/выручки","zh":"确定公平的房屋/收益分配","ar":"تحديد تقاسم عادل للشقق/العائدات"},"Noter Sözleşmesi":{"en":"Notary Contract","ru":"Нотариальный договор","zh":"公证合同","ar":"عقد كاتب العدل"},"Tapuya şerhli, cezai şartlı kat karşılığı sözleşmesi":{"en":"Land-for-flat contract annotated on the deed, with a penal clause","ru":"Договор в обмен на квартиры с отметкой в свидетельстве и штрафным условием","zh":"在产权证上批注、含违约条款的以房换地合同","ar":"عقد الإنشاء مقابل حصص شقق مُدوَّن شرحًا على صحيفة الملكية وبشرط جزائي"},"Proje, Ruhsat & İnşaat":{"en":"Design, Permit & Construction","ru":"Проект, разрешение и строительство","zh":"设计、许可与施工","ar":"التصميم والرخصة والإنشاء"},"Mimari-statik proje, yapı ruhsatı ve yapı denetimli yapım":{"en":"Architectural-structural design, building permit and inspected construction","ru":"Архитектурно-конструктивный проект, разрешение на строительство и поднадзорное строительство","zh":"建筑-结构设计、建筑许可与受监理施工","ar":"تصميم معماري-إنشائي، رخصة بناء وإنشاء مُدقَّق"},"Paylaşım & Teslim":{"en":"Split & Handover","ru":"Раздел и сдача","zh":"分配与交付","ar":"التقاسم والتسليم"},"Kademeli tapu devri ve bağımsız bölüm teslimi":{"en":"Staged title transfer and unit handover","ru":"Поэтапная передача права собственности и сдача самостоятельных помещений","zh":"分阶段产权转让与独立单元交付","ar":"نقل ملكية مرحلي وتسليم الوحدات المستقلة"},"Arsa Payı Karşılığı Sözleşme":{"en":"Land-Share Contract","ru":"Договор в обмен на долю участка","zh":"以地块份额为对价的合同","ar":"عقد مقابل حصة من الأرض"},"Tapu & Kat İrtifakı":{"en":"Title Deed & Construction Servitude","ru":"Свидетельство о собственности и сервитут застройки","zh":"产权证与建筑地役权","ar":"صحيفة الملكية وحق ارتفاق البناء"},"TBK Cezai Şart":{"en":"Penal Clause (Code of Obligations)","ru":"Штрафное условие (Обязательственный кодекс)","zh":"违约条款（债务法）","ar":"الشرط الجزائي (قانون الالتزامات)"},"Arsam için paylaşım teklifi →":{"en":"A share offer for my plot →","ru":"Предложение о разделе для моего участка →","zh":"为我的地块获取分配方案 →","ar":"عرض تقاسم لأرضي →"},"Teminat ipoteği":{"en":"Security mortgage","ru":"Обеспечительная ипотека","zh":"担保抵押","ar":"رهن ضمان"},"Noter sözleşme":{"en":"Notary contract","ru":"Нотариальный договор","zh":"公证合同","ar":"عقد كاتب العدل"},"Tadilat & Renovasyon — Daire, Ofis & Bina":{"en":"Renovation & Refurbishment — Flat, Office & Building","ru":"Ремонт и реновация — квартира, офис и здание","zh":"翻新与改造 — 公寓、办公室与整栋建筑","ar":"التجديد والتحديث — شقة ومكتب ومبنى"},"Daire, ofis ve bina genelinde komple tadilat, yenileme ve iç mekân renovasyonunu tek elden yönetiyoruz.":{"en":"We manage complete renovation, refurbishment and interior remodelling across flats, offices and whole buildings from a single source.","ru":"Мы управляем комплексным ремонтом, обновлением и реновацией интерьера квартир, офисов и зданий из одних рук.","zh":"我们一站式管理公寓、办公室及整栋建筑范围内的整体翻新、更新与室内改造。","ar":"ندير من جهة واحدة التجديد الشامل والتحديث وترميم الديكور الداخلي على نطاق الشقة والمكتب والمبنى."},"En önemli farkımız şudur: taşıyıcı sisteme (kolon-kiriş-perde) asla izinsiz müdahale etmeyiz. Kolon, kiriş ve perde duvarların kesilmesi yapının deprem davranışını bozar ve mevzuata göre suç teşkil eder; böyle bir ihtiyaç doğduğunda yalnızca statik mühendis raporu ve gerekiyorsa güçlendirme ruhsatıyla çalışırız. Boya, zemin ve dolap gibi işler ruhsat gerektirmezken; duvar kaldırma, ıslak hacim yeri değiştirme ve tesisat değişikliği belediye izni ve çoğu zaman kat malikleri onayı ister. Tipik bir 95-115 m² komple daire tadilatı yaklaşık 5-8 haftada tamamlanır; süreci yazılı sözleşme, sabit fiyat ve günlük ilerleme paylaşımıyla yürütürüz.":{"en":"Our most important difference is this: we never touch the structural system (columns-beams-shear walls) without authorisation. Cutting columns, beams and shear walls disrupts the building's seismic behaviour and constitutes an offence under the regulations; when such a need arises, we work only with a structural engineer's report and, if required, a strengthening permit. While work such as painting, flooring and cabinetry needs no permit, removing a wall, relocating a wet area and altering the plumbing require municipal permission and, in most cases, the approval of the flat owners. A typical complete renovation of a 95-115 m² flat is finished in roughly 5-8 weeks; we run the process with a written contract, a fixed price and daily progress updates.","ru":"Наше важнейшее отличие в том, что мы никогда не вмешиваемся в несущую систему (колонны-балки-диафрагмы) без разрешения. Резка колонн, балок и несущих стен нарушает сейсмическое поведение здания и по нормам является правонарушением; при возникновении такой необходимости мы работаем только на основании отчёта инженера-конструктора и, при необходимости, разрешения на усиление. Тогда как покраска, полы и шкафы не требуют разрешения, снос стены, перенос мокрой зоны и изменение инженерных сетей требуют разрешения муниципалитета и в большинстве случаев согласия собственников квартир. Типичный комплексный ремонт квартиры 95-115 м² завершается примерно за 5-8 недель; процесс мы ведём с письменным договором, фиксированной ценой и ежедневным информированием о ходе работ.","zh":"我们最重要的区别在于：未经许可，我们绝不触动承重体系（柱-梁-剪力墙）。切割柱、梁与剪力墙会破坏建筑的抗震性能，并依法构成违法行为；一旦出现此类需求，我们仅在结构工程师报告以及必要时的加固许可下作业。涂料、地面与橱柜等工作无需许可，而拆墙、移动湿区与改动管线则需要市政许可，且多数情况下需要业主的同意。一套 95-115 m² 的公寓整体翻新通常约在 5-8 周内完成；我们以书面合同、固定价格与每日进度通报推进流程。","ar":"أهم ما يميّزنا هو التالي: لا نمسّ إطلاقًا النظام الإنشائي (أعمدة-كمرات-جدران قص) دون إذن. فقطع الأعمدة والكمرات والجدران الحاملة يخلّ بالسلوك الزلزالي للمبنى ويُعدّ جريمة وفق الأنظمة؛ وعند نشوء حاجة كهذه نعمل فقط بتقرير مهندس إنشائي وعند اللزوم برخصة تقوية. وبينما لا تحتاج أعمال كالدهان والأرضيات والخزائن إلى رخصة، فإن إزالة جدار ونقل منطقة رطبة وتعديل التمديدات تتطلب إذن البلدية وفي غالب الأحيان موافقة مُلّاك الشقق. ويكتمل التجديد الشامل النموذجي لشقة مساحتها 95-115 م² في نحو 5-8 أسابيع؛ وندير المسار بعقد مكتوب وسعر ثابت وإطلاع يومي على التقدم."},"Komple iç mekân yenileme":{"en":"Complete interior renewal","ru":"Комплексное обновление интерьера","zh":"整体室内更新","ar":"تجديد داخلي شامل"},"Elektrik & sıhhi tesisat yenileme":{"en":"Electrical & plumbing renewal","ru":"Обновление электрики и сантехники","zh":"电气与给排水更新","ar":"تجديد الكهرباء والتمديدات الصحية"},"Mutfak & banyo (ıslak hacim) dönüşümü":{"en":"Kitchen & bathroom (wet area) transformation","ru":"Преобразование кухни и ванной (мокрой зоны)","zh":"厨房与卫浴（湿区）改造","ar":"تحويل المطبخ والحمام (المنطقة الرطبة)"},"Alçıpan, asma tavan, boya, zemin kaplama":{"en":"Drywall, suspended ceiling, paint, floor covering","ru":"Гипсокартон, подвесной потолок, покраска, напольное покрытие","zh":"石膏板、吊顶、涂料、地面铺装","ar":"ألواح جبسية، سقف مستعار، دهان، تكسية أرضيات"},"Kapı-pencere & cephe yenileme":{"en":"Door-window & façade renewal","ru":"Обновление дверей-окон и фасада","zh":"门窗与立面更新","ar":"تجديد الأبواب-النوافذ والواجهة"},"Su kaçağı tespiti & çatlak onarımı":{"en":"Leak detection & crack repair","ru":"Обнаружение протечек и ремонт трещин","zh":"漏水检测与裂缝修补","ar":"كشف تسرب المياه وإصلاح الشقوق"},"Keşif & Ölçüm":{"en":"Survey & Measurement","ru":"Осмотр и обмеры","zh":"勘察与测量","ar":"المعاينة والقياس"},"Yerinde keşif, ölçüm ve kalem kalem detaylı teklif":{"en":"On-site survey, measurement and an itemised detailed quote","ru":"Осмотр на месте, обмеры и детальное постатейное предложение","zh":"现场勘察、测量与逐项详细报价","ar":"معاينة ميدانية وقياس وعرض تفصيلي بندًا بندًا"},"3D Tasarım & Malzeme":{"en":"3D Design & Materials","ru":"3D-дизайн и материалы","zh":"3D 设计与材料","ar":"تصميم ثلاثي الأبعاد ومواد"},"Görselleştirme, malzeme seçimi ve yazılı sözleşme":{"en":"Visualisation, material selection and a written contract","ru":"Визуализация, выбор материалов и письменный договор","zh":"可视化、材料选择与书面合同","ar":"التصوّر البصري واختيار المواد وعقد مكتوب"},"Söküm / Yıkım":{"en":"Stripping / Demolition","ru":"Демонтаж / снос","zh":"拆除 / 拆卸","ar":"الفك / الهدم"},"Kontrollü söküm, moloz tahliyesi ve gizli hasar tespiti":{"en":"Controlled stripping, debris removal and hidden-damage detection","ru":"Контролируемый демонтаж, вывоз мусора и выявление скрытых повреждений","zh":"受控拆卸、渣土清运与隐蔽损坏排查","ar":"فك مضبوط وإخلاء الأنقاض وكشف الأضرار الخفية"},"Tesisat & İnce İşler":{"en":"Utilities & Finishing","ru":"Инженерные сети и чистовые работы","zh":"管线与精装工程","ar":"التمديدات وأعمال التشطيب"},"Elektrik-su tesisatı, alçıpan, seramik, boya, montaj":{"en":"Electrical-plumbing, drywall, tiling, paint, installation","ru":"Электрика-сантехника, гипсокартон, керамика, покраска, монтаж","zh":"电气-给排水、石膏板、瓷砖、涂料、安装","ar":"تمديدات كهرباء-مياه، ألواح جبسية، سيراميك، دهان، تركيب"},"Temizlik & Teslim":{"en":"Cleaning & Handover","ru":"Уборка и сдача","zh":"清洁与交付","ar":"التنظيف والتسليم"},"İnce temizlik, kontrol listesi ve teslim":{"en":"Fine cleaning, checklist and handover","ru":"Финальная уборка, контрольный лист и сдача","zh":"精细清洁、检查清单与交付","ar":"تنظيف دقيق وقائمة تحقق وتسليم"},"Tadilat/İmar Ruhsatı":{"en":"Renovation/Zoning Permit","ru":"Разрешение на ремонт/зонирование","zh":"翻新/规划许可","ar":"رخصة تجديد/تنظيم عمراني"},"Kat Mülkiyeti Kanunu 634":{"en":"Condominium Law 634","ru":"Закон о кондоминиуме 634","zh":"住宅产权法 634","ar":"قانون الملكية العقارية 634"},"Tadilat keşfi & teklifi al →":{"en":"Get a renovation survey & quote →","ru":"Получить осмотр и предложение по ремонту →","zh":"获取翻新勘察与报价 →","ar":"احصل على معاينة وعرض للتجديد →"},"Statik onaylı":{"en":"Structurally approved","ru":"Согласовано конструктором","zh":"结构审核通过","ar":"معتمد إنشائيًا"},"Mevcut yapılarda deprem güçlendirmesi ve tarihi yapı restorasyonunu, önce performans analiziyle teşhis koyarak yapıyoruz.":{"en":"We carry out seismic retrofitting of existing buildings and the restoration of historic structures — first diagnosing with a performance analysis.","ru":"Мы выполняем сейсмическое усиление существующих зданий и реставрацию исторических сооружений, сначала ставя диагноз с помощью анализа характеристик.","zh":"我们对既有建筑进行抗震加固、对历史建筑进行修复，先以性能分析作出诊断。","ar":"ننفّذ التقوية الزلزالية للمباني القائمة وترميم المباني التاريخية، مع وضع التشخيص أولًا عبر تحليل الأداء."},"Güçlendirmenin ilk adımı doğru teşhistir: karot numunesiyle beton dayanımı, donatı tespiti ve TBDY 2018'e göre performans analizi yapılır. Sonuca göre karbon fiber (CFRP), betonarme mantolama/çelik ceket veya yeni perde ekleme yöntemlerinden uygun olanı seçilir. CFRP; çelikten kat kat yüksek çekme dayanımı ve düşük ağırlığıyla, binayı boşaltmadan hızlı uygulama imkânı sunar ve genelde 30-90 günde tamamlanır. Kentsel dönüşümde imar hakkı (kat/metrekare) korunacaksa güçlendirme güçlü bir alternatiftir. Tarihi yapılarda süreç röleve, restitüsyon ve restorasyon aşamalarıyla, Koruma Kurulu onaylarına bağlı yürütülür.":{"en":"The first step of retrofitting is an accurate diagnosis: concrete strength via core samples, reinforcement detection and a performance analysis to TBDY 2018 are carried out. Based on the result, the appropriate method is chosen among carbon fibre (CFRP), reinforced-concrete jacketing/steel jacketing or adding new shear walls. With tensile strength many times higher than steel and low weight, CFRP allows rapid application without vacating the building and is generally completed in 30-90 days. In urban renewal, retrofitting is a strong alternative when the zoning rights (floors/square metres) are to be preserved. In historic buildings, the process is carried out through survey, restitution and restoration stages, subject to the approvals of the Conservation Board.","ru":"Первый шаг усиления — точная диагностика: определяются прочность бетона по образцам кернов, расположение арматуры и проводится анализ характеристик по TBDY 2018. По результату выбирается подходящий метод из числа углеродного волокна (CFRP), железобетонной обоймы/стальной обоймы или добавления новых диафрагм. Углеродное волокно (CFRP) благодаря прочности на растяжение, во много раз превышающей стальную, и малому весу позволяет вести быстрое применение без отселения здания и обычно завершается за 30-90 дней. В городской реновации, если требуется сохранить права застройки (этажи/квадратные метры), усиление является сильной альтернативой. В исторических зданиях процесс ведётся через этапы обмерного чертежа, реституции и реставрации и зависит от согласований Совета по охране.","zh":"加固的第一步是准确诊断：通过取芯样测定混凝土强度、探测钢筋，并按 TBDY 2018 进行性能分析。根据结果，在碳纤维（CFRP）、钢筋混凝土套箍/钢套箍或新增剪力墙等方法中选择合适者。碳纤维（CFRP）凭借数倍于钢材的抗拉强度与轻质，可在不腾空建筑的情况下快速施工，通常在 30-90 天内完成。在城市更新中，若需保留建筑权利（层数/平方米），加固是一种有力的替代方案。对历史建筑，流程通过测绘、复原与修复各阶段进行，并取决于文物保护委员会的批准。","ar":"الخطوة الأولى للتقوية هي التشخيص الدقيق: تُحدَّد مقاومة الخرسانة عبر العينات اللبّية، ويُكشف حديد التسليح، ويُجرى تحليل أداء وفق TBDY 2018. وبناءً على النتيجة يُختار المنهج المناسب من بين ألياف الكربون (CFRP) أو التغليف الخرساني/الغلاف الفولاذي أو إضافة جدران قص جديدة. وتوفّر ألياف الكربون (CFRP) بمقاومة شدّ تفوق الفولاذ أضعافًا ووزن منخفض إمكانية تطبيق سريع دون إخلاء المبنى، وتكتمل عادةً في 30-90 يومًا. وفي التحول الحضري، إذا أُريد الحفاظ على حقوق البناء (طوابق/أمتار مربعة) تكون التقوية بديلًا قويًا. وفي المباني التاريخية يسير المسار عبر مراحل الرفع المساحي وإعادة التكوين والترميم، ويرتبط بموافقات مجلس الحفاظ."},"Deprem performans analizi":{"en":"Seismic performance analysis","ru":"Анализ сейсмических характеристик","zh":"抗震性能分析","ar":"تحليل الأداء الزلزالي"},"Karbon fiber (FRP) güçlendirme":{"en":"Carbon-fibre (FRP) strengthening","ru":"Усиление углеродным волокном (FRP)","zh":"碳纤维（FRP）加固","ar":"تقوية بألياف الكربون (FRP)"},"Perde & kolon mantolama":{"en":"Shear-wall & column jacketing","ru":"Обоймирование диафрагм и колонн","zh":"剪力墙与柱套箍","ar":"تغليف جدران القص والأعمدة"},"Temel güçlendirme":{"en":"Foundation strengthening","ru":"Усиление фундамента","zh":"基础加固","ar":"تقوية الأساسات"},"Tarihi yapı restorasyonu":{"en":"Historic-building restoration","ru":"Реставрация исторических зданий","zh":"历史建筑修复","ar":"ترميم المباني التاريخية"},"Röleve & restitüsyon projesi":{"en":"Survey & restitution project","ru":"Проект обмерного чертежа и реституции","zh":"测绘与复原设计","ar":"مشروع الرفع المساحي وإعادة التكوين"},"Analiz":{"en":"Analysis","ru":"Анализ","zh":"分析","ar":"التحليل"},"Karot, donatı tespiti ve TBDY 2018 performans değerlendirmesi":{"en":"Core sampling, reinforcement detection and a TBDY 2018 performance assessment","ru":"Отбор кернов, определение арматуры и оценка характеристик по TBDY 2018","zh":"取芯、钢筋探测与 TBDY 2018 性能评估","ar":"أخذ العينات اللبّية، كشف التسليح وتقييم الأداء وفق TBDY 2018"},"Proje":{"en":"Design","ru":"Проект","zh":"设计","ar":"التصميم"},"Güçlendirme veya restorasyon projesinin hazırlanması":{"en":"Preparation of the strengthening or restoration project","ru":"Подготовка проекта усиления или реставрации","zh":"加固或修复设计的编制","ar":"إعداد مشروع التقوية أو الترميم"},"Uygulama":{"en":"Application","ru":"Применение","zh":"施工","ar":"التنفيذ"},"Kontrollü FRP / mantolama / perde güçlendirme işleri":{"en":"Controlled FRP / jacketing / shear-wall strengthening works","ru":"Контролируемые работы по усилению FRP / обоймой / диафрагмами","zh":"受控的 FRP / 套箍 / 剪力墙加固作业","ar":"أعمال تقوية مضبوطة بـ FRP / تغليف / جدران قص"},"Onay & Teslim":{"en":"Approval & Handover","ru":"Согласование и сдача","zh":"审批与交付","ar":"الاعتماد والتسليم"},"Test, raporlama ve (tarihi yapıda) kurul onayı":{"en":"Testing, reporting and (for historic buildings) board approval","ru":"Испытания, отчётность и (для исторических зданий) согласование совета","zh":"测试、报告以及（历史建筑的）委员会批准","ar":"الاختبار والتوثيق و(في المباني التاريخية) موافقة المجلس"},"Koruma Kurulu":{"en":"Conservation Board","ru":"Совет по охране","zh":"文物保护委员会","ar":"مجلس الحفاظ"},"Güçlendirme analizi talep et →":{"en":"Request a retrofitting analysis →","ru":"Запросить анализ усиления →","zh":"申请加固分析 →","ar":"اطلب تحليل تقوية →"},"Karbon fiber (FRP)":{"en":"Carbon fibre (FRP)","ru":"Углеродное волокно (FRP)","zh":"碳纤维（FRP）","ar":"ألياف الكربون (FRP)"},"Performans analizi":{"en":"Performance analysis","ru":"Анализ характеристик","zh":"性能分析","ar":"تحليل الأداء"},"Ticari & Karma Kullanımlı Yapılar":{"en":"Commercial & Mixed-Use Buildings","ru":"Коммерческие и многофункциональные здания","zh":"商业与综合体建筑","ar":"المباني التجارية والمختلطة الاستخدام"},"Ofis, plaza, AVM, otel ve karma kullanımlı (mixed-use) projelerde; yönetmeliklere tam uyumlu, sertifikalı ve akıllı bina yönetimli yapılar üretiyoruz.":{"en":"For office, plaza, mall, hotel and mixed-use projects, we deliver fully code-compliant, certified buildings with smart building management.","ru":"Для офисов, бизнес-центров, ТЦ, отелей и многофункциональных (mixed-use) проектов мы возводим полностью соответствующие нормам, сертифицированные здания с системой «умного» управления.","zh":"在办公、商务楼、购物中心、酒店及综合体（mixed-use）项目中，我们建造完全符合法规、经过认证并配备智能楼宇管理的建筑。","ar":"في مشاريع المكاتب والأبراج والمولات والفنادق والمشاريع المختلطة الاستخدام (mixed-use)، ننجز مبانٍ متوافقة تمامًا مع الأنظمة، معتمدة ومزوّدة بإدارة مبنى ذكية."},"Ticari yapılarda başarı, yaşam güvenliği ve işletme yönetmeliklerine uyumla başlar. Yangın kompartımanları, kaçış yolları ve sprinkler sistemleri BYKHY'ye göre; otopark kapasitesi Otopark Yönetmeliği hesabına göre; işlev ise İşyeri Açma ve Çalışma Ruhsatı Yönetmeliği'ne göre tasarlanır. Geniş açıklık ve yüksek yük gerektiren mekânlarda çelik konstrüksiyon, bina yükseklik sınıfına uygun taşıyıcı çözümlerle birlikte kullanılır. Kurumsal kiracı ve yatırımcı güveni için LEED/BREEAM yeşil bina sertifikaları ve akıllı bina yönetim sistemleri (BMS) standart hedefimizdir; enerji, aydınlatma, HVAC ve güvenlik tek merkezden yönetilerek işletme maliyeti düşürülür.":{"en":"Success in commercial buildings starts with life safety and compliance with operating regulations. Fire compartments, escape routes and sprinkler systems are designed to the Fire Protection Regulation (BYKHY); parking capacity to the Parking Regulation calculation; and function to the Business Opening and Operating Licence Regulation. In spaces requiring long spans and high loads, steel construction is used together with structural solutions appropriate to the building height class. For the confidence of corporate tenants and investors, LEED/BREEAM green-building certificates and building management systems (BMS) are our standard target; energy, lighting, HVAC and security are managed from a single centre to lower operating costs.","ru":"Успех коммерческих зданий начинается с безопасности жизни и соответствия эксплуатационным нормам. Противопожарные отсеки, пути эвакуации и спринклерные системы проектируются по BYKHY; вместимость парковки — по расчёту Правил парковки; а функция — по Правилам открытия и работы предприятия. В помещениях, требующих больших пролётов и высоких нагрузок, стальные конструкции применяются вместе с несущими решениями, соответствующими классу высотности здания. Для доверия корпоративных арендаторов и инвесторов «зелёные» сертификаты LEED/BREEAM и системы управления зданием (BMS) — наша стандартная цель; энергия, освещение, HVAC и безопасность управляются из единого центра, снижая эксплуатационные расходы.","zh":"商业建筑的成功始于生命安全与运营法规的合规。防火分区、疏散通道与喷淋系统按 BYKHY 设计；停车容量按《停车规程》计算；功能则按《营业场所开办与经营许可规程》设计。在需要大跨度与高荷载的空间，钢结构与符合建筑高度等级的承重方案配合使用。为赢得企业租户与投资者的信任，LEED/BREEAM 绿色建筑认证与楼宇管理系统（BMS）是我们的标准目标；能源、照明、暖通空调（HVAC）与安防由单一中心统一管理，以降低运营成本。","ar":"يبدأ النجاح في المباني التجارية بسلامة الأرواح والتوافق مع أنظمة التشغيل. تُصمَّم فواصل الحريق ومسارات الهروب وأنظمة الرش وفق BYKHY؛ وسعة مواقف السيارات وفق حساب لائحة المواقف؛ والوظيفة وفق لائحة فتح وتشغيل المنشأة. وفي الفراغات التي تتطلب بحورًا واسعة وأحمالًا عالية، يُستخدم الإنشاء الفولاذي مع حلول إنشائية ملائمة لصنف ارتفاع المبنى. ولنيل ثقة المستأجرين المؤسسيين والمستثمرين، تُعدّ شهادات المباني الخضراء LEED/BREEAM وأنظمة إدارة المبنى (BMS) هدفنا المعياري؛ إذ تُدار الطاقة والإضاءة والتكييف (HVAC) والأمن من مركز واحد لخفض تكلفة التشغيل."},"Ofis & plaza yapımı":{"en":"Office & plaza construction","ru":"Строительство офисов и бизнес-центров","zh":"办公楼与商务楼建造","ar":"إنشاء المكاتب والأبراج"},"AVM & perakende alanları":{"en":"Mall & retail spaces","ru":"ТЦ и торговые площади","zh":"购物中心与零售空间","ar":"المولات ومساحات التجزئة"},"Otel & konaklama tesisleri":{"en":"Hotel & hospitality facilities","ru":"Отели и объекты гостеприимства","zh":"酒店与接待设施","ar":"الفنادق ومنشآت الضيافة"},"Karma kullanım (mixed-use) projeleri":{"en":"Mixed-use projects","ru":"Многофункциональные (mixed-use) проекты","zh":"综合体（mixed-use）项目","ar":"المشاريع المختلطة الاستخدام (mixed-use)"},"LEED / BREEAM sertifikasyon":{"en":"LEED / BREEAM certification","ru":"Сертификация LEED / BREEAM","zh":"LEED / BREEAM 认证","ar":"اعتماد LEED / BREEAM"},"Akıllı bina (BMS) sistemleri":{"en":"Smart-building (BMS) systems","ru":"Системы «умного» здания (BMS)","zh":"智能建筑（BMS）系统","ar":"أنظمة المبنى الذكي (BMS)"},"Konsept & Fizibilite":{"en":"Concept & Feasibility","ru":"Концепция и ТЭО","zh":"概念与可行性","ar":"المفهوم ودراسة الجدوى"},"Kullanım analizi, gelir modeli ve fizibilite":{"en":"Usage analysis, revenue model and feasibility","ru":"Анализ использования, модель доходов и ТЭО","zh":"使用分析、收益模型与可行性","ar":"تحليل الاستخدام ونموذج الإيرادات ودراسة الجدوى"},"Tasarım":{"en":"Design","ru":"Проектирование","zh":"设计","ar":"التصميم"},"Mimari, MEP ve sertifika (LEED/BREEAM) hedefleri":{"en":"Architectural, MEP and certification (LEED/BREEAM) targets","ru":"Архитектура, MEP и цели сертификации (LEED/BREEAM)","zh":"建筑、机电与认证（LEED/BREEAM）目标","ar":"أهداف العمارة والـ MEP والاعتماد (LEED/BREEAM)"},"Ruhsat & Onaylar":{"en":"Permits & Approvals","ru":"Разрешения и согласования","zh":"许可与批准","ar":"الرخص والموافقات"},"Yangın, otopark ve işyeri açma uyum onayları":{"en":"Fire, parking and business-opening compliance approvals","ru":"Согласования по пожарной безопасности, парковке и открытию предприятия","zh":"消防、停车与营业开办合规批准","ar":"موافقات التوافق للحريق والمواقف وفتح المنشأة"},"Yapım & MEP":{"en":"Construction & MEP","ru":"Строительство и MEP","zh":"施工与机电","ar":"الإنشاء والـ MEP"},"Çelik/betonarme yapım, mekanik-elektrik tesisat":{"en":"Steel/reinforced-concrete construction, mechanical-electrical systems","ru":"Стальное/железобетонное строительство, механические-электрические сети","zh":"钢/钢筋混凝土施工、机械-电气管线","ar":"إنشاء فولاذي/خرساني مسلح، تمديدات ميكانيكية-كهربائية"},"Devreye Alma":{"en":"Commissioning","ru":"Пусконаладка","zh":"调试","ar":"التشغيل التجريبي"},"Test, işletmeye alma ve teknik destek":{"en":"Testing, bringing into operation and technical support","ru":"Испытания, ввод в эксплуатацию и техническая поддержка","zh":"测试、投入运营与技术支持","ar":"الاختبار والإدخال في الخدمة والدعم الفني"},"İşyeri Açma Ruhsatı":{"en":"Business Opening Licence","ru":"Разрешение на открытие предприятия","zh":"营业开办许可","ar":"رخصة فتح المنشأة"},"Yangın Yönetmeliği (BYKHY)":{"en":"Fire Protection Regulation (BYKHY)","ru":"Правила пожарной безопасности (BYKHY)","zh":"消防规程（BYKHY）","ar":"لائحة الحريق (BYKHY)"},"Otopark Yönetmeliği":{"en":"Parking Regulation","ru":"Правила парковки","zh":"停车规程","ar":"لائحة المواقف"},"Ticari proje görüşmesi →":{"en":"Discuss a commercial project →","ru":"Обсудить коммерческий проект →","zh":"洽谈商业项目 →","ar":"مناقشة مشروع تجاري →"},"Akıllı bina (BMS)":{"en":"Smart building (BMS)","ru":"«Умное» здание (BMS)","zh":"智能建筑（BMS）","ar":"المبنى الذكي (BMS)"},"Endüstriyel Yapılar — Fabrika, Depo & Lojistik":{"en":"Industrial Buildings — Factory, Warehouse & Logistics","ru":"Промышленные здания — завод, склад и логистика","zh":"工业建筑 — 工厂、仓库与物流","ar":"المباني الصناعية — مصنع ومستودع ولوجستيات"},"Fabrika, depo ve lojistik tesislerinde; geniş açıklıklı çelik konstrüksiyon, prefabrik betonarme ve hızlı yapım teknikleriyle üretime hazır yapılar kuruyoruz.":{"en":"For factories, warehouses and logistics facilities, we build production-ready structures with long-span steel construction, precast reinforced concrete and rapid-build techniques.","ru":"На заводах, складах и логистических объектах мы возводим готовые к производству сооружения с большепролётными стальными конструкциями, сборным железобетоном и технологиями быстрого строительства.","zh":"在工厂、仓库与物流设施中，我们以大跨度钢结构、预制钢筋混凝土与快速建造技术建成即可投产的建筑。","ar":"في المصانع والمستودعات والمنشآت اللوجستية، نقيم مبانٍ جاهزة للإنتاج بإنشاء فولاذي واسع البحور وخرسانة مسلحة سابقة الصنع وتقنيات بناء سريع."},"Endüstriyel yapılarda tasarımı belirleyen üç ölçüt vardır: açıklık, yük ve hız. Geniş açıklıklı üretim ve depo hacimleri, kolonsuz alan sağlayan çelik konstrüksiyonla; tekrarlı ve hızlı yapım gereken bölümler prefabrik betonarme sistemlerle çözülür. Çatı sistemleri kar, rüzgâr ve ekipman yüklerine göre boyutlandırılır. Saha montajı, atölyede üretilen elemanların hızlı kurulumuyla proje süresini kısaltır; tüm süreç iş sağlığı ve güvenliği (6331) planı, yüksekte çalışma ve kaldırma güvenliği protokolleriyle yürütülür ve teslim devreye alma testleriyle tamamlanır.":{"en":"Three criteria drive the design of industrial buildings: span, load and speed. Long-span production and storage volumes are solved with steel construction that provides column-free space; sections requiring repetitive and rapid building are solved with precast reinforced-concrete systems. Roof systems are sized for snow, wind and equipment loads. Site assembly shortens the project duration through rapid installation of workshop-fabricated elements; the entire process is carried out with an occupational health and safety (6331) plan and working-at-height and lifting-safety protocols, and delivery is completed with commissioning tests.","ru":"Проектирование промышленных зданий определяют три критерия: пролёт, нагрузка и скорость. Большепролётные производственные и складские объёмы решаются стальными конструкциями, обеспечивающими пространство без колонн; участки, требующие повторяющегося и быстрого строительства, — сборными железобетонными системами. Кровельные системы рассчитываются на снеговые, ветровые нагрузки и нагрузки от оборудования. Монтаж на площадке сокращает срок проекта за счёт быстрой установки изготовленных в цеху элементов; весь процесс ведётся с планом охраны труда и техники безопасности (6331), протоколами работы на высоте и безопасности подъёма, а сдача завершается пусконаладочными испытаниями.","zh":"决定工业建筑设计的有三项标准：跨度、荷载与速度。大跨度的生产与仓储空间以提供无柱空间的钢结构解决；需要重复且快速建造的部分以预制钢筋混凝土体系解决。屋面体系按雪、风与设备荷载进行设计。现场装配通过工厂预制构件的快速安装缩短工期；整个流程以职业健康安全（6331）计划、高处作业与吊装安全规程推进，交付以调试测试完成。","ar":"ثلاثة معايير تحدد تصميم المباني الصناعية: البحر والحمل والسرعة. تُحلّ فراغات الإنتاج والتخزين واسعة البحور بإنشاء فولاذي يوفّر فضاءً بلا أعمدة؛ وتُحلّ الأجزاء التي تتطلب بناءً متكررًا وسريعًا بأنظمة الخرسانة المسلحة سابقة الصنع. وتُصمَّم أنظمة الأسقف وفق أحمال الثلج والرياح والمعدات. ويختصر التركيب في الموقع مدة المشروع عبر التركيب السريع للعناصر المصنّعة في الورشة؛ ويسير المسار كله بخطة السلامة والصحة المهنية (6331) وبروتوكولات العمل على ارتفاع وسلامة الرفع، ويكتمل التسليم باختبارات التشغيل التجريبي."},"Çelik konstrüksiyon yapım":{"en":"Steel-construction build","ru":"Строительство стальных конструкций","zh":"钢结构建造","ar":"إنشاء فولاذي"},"Prefabrik betonarme sistemler":{"en":"Precast reinforced-concrete systems","ru":"Сборные железобетонные системы","zh":"预制钢筋混凝土体系","ar":"أنظمة خرسانة مسلحة سابقة الصنع"},"Geniş açıklıklı çatı sistemleri":{"en":"Long-span roof systems","ru":"Большепролётные кровельные системы","zh":"大跨度屋面体系","ar":"أنظمة أسقف واسعة البحور"},"Lojistik & depo tesisleri":{"en":"Logistics & warehouse facilities","ru":"Логистические и складские объекты","zh":"物流与仓储设施","ar":"منشآت لوجستية ومستودعات"},"Üretim & fabrika binaları":{"en":"Production & factory buildings","ru":"Производственные и заводские здания","zh":"生产与工厂建筑","ar":"مباني إنتاج ومصانع"},"Altyapı & saha düzenleme":{"en":"Infrastructure & site development","ru":"Инфраструктура и благоустройство площадки","zh":"基础设施与场地整理","ar":"بنية تحتية وتهيئة الموقع"},"İhtiyaç Analizi":{"en":"Needs Analysis","ru":"Анализ потребностей","zh":"需求分析","ar":"تحليل الاحتياجات"},"Üretim akışı, yük, açıklık ve alan ihtiyaçları":{"en":"Production flow, load, span and space requirements","ru":"Производственный поток, нагрузка, пролёт и потребности в площади","zh":"生产流程、荷载、跨度与场地需求","ar":"تدفق الإنتاج والحمل والبحر واحتياجات المساحة"},"Çelik/prefabrik sistem ve çatı statiği tasarımı":{"en":"Steel/precast system and roof-structure design","ru":"Проектирование стальной/сборной системы и статики кровли","zh":"钢/预制体系与屋面结构设计","ar":"تصميم النظام الفولاذي/سابق الصنع وإنشائيات السقف"},"İmalat & Montaj":{"en":"Fabrication & Assembly","ru":"Изготовление и монтаж","zh":"制作与安装","ar":"التصنيع والتركيب"},"Atölye imalatı ve hızlı saha montajı":{"en":"Workshop fabrication and rapid site assembly","ru":"Цеховое изготовление и быстрый монтаж на площадке","zh":"工厂制作与快速现场安装","ar":"تصنيع في الورشة وتركيب سريع في الموقع"},"Devreye alma, İSG onayı ve teslim":{"en":"Commissioning, OHS approval and handover","ru":"Пусконаладка, согласование охраны труда и сдача","zh":"调试、职业安全批准与交付","ar":"التشغيل التجريبي، موافقة السلامة المهنية والتسليم"},"İş Sağlığı & Güvenliği 6331":{"en":"Occupational Health & Safety 6331","ru":"Охрана труда и техника безопасности 6331","zh":"职业健康与安全 6331","ar":"السلامة والصحة المهنية 6331"},"Endüstriyel tesis için teklif →":{"en":"A quote for an industrial facility →","ru":"Предложение для промышленного объекта →","zh":"为工业设施获取报价 →","ar":"عرض لمنشأة صناعية →"},"Çelik konstrüksiyon":{"en":"Steel construction","ru":"Стальные конструкции","zh":"钢结构","ar":"إنشاء فولاذي"},"Hızlı yapım":{"en":"Rapid build","ru":"Быстрое строительство","zh":"快速建造","ar":"بناء سريع"},"Nasıl çalışıyoruz?":{"en":"How do we work?","ru":"Как мы работаем?","zh":"我们如何工作？","ar":"كيف نعمل؟"},"Hangi hizmeti alırsanız alın, süreç aynı disiplinle işler: önce veri, sonra sözleşme, sonra denetimli üretim ve belgeli teslim.":{"en":"Whichever service you choose, the process runs with the same discipline: data first, then the contract, then inspected production and documented handover.","ru":"Какую бы услугу вы ни выбрали, процесс идёт с одной и той же дисциплиной: сначала данные, затем договор, затем поднадзорное производство и документированная сдача.","zh":"无论您选择哪项服务，流程都以同样的纪律运行：先数据，再合同，然后受监理生产与凭证交付。","ar":"أيًّا كانت الخدمة التي تختارها، يسير المسار بالانضباط نفسه: البيانات أولًا، ثم العقد، ثم إنتاج مُدقَّق وتسليم موثّق."},"Keşif & Analiz":{"en":"Survey & Analysis","ru":"Осмотр и анализ","zh":"勘察与分析","ar":"المعاينة والتحليل"},"Yerinde keşif, imar-zemin analizi ve fizibilite. Karar duyguyla değil veriyle verilir.":{"en":"On-site survey, zoning-soil analysis and feasibility. The decision is made with data, not emotion.","ru":"Осмотр на месте, анализ зонирования-грунта и ТЭО. Решение принимается на основе данных, а не эмоций.","zh":"现场勘察、规划-地质分析与可行性。决策以数据而非情绪作出。","ar":"معاينة ميدانية، تحليل التنظيم العمراني-التربة ودراسة جدوى. يُتخذ القرار بالبيانات لا بالعاطفة."},"Sabit götürü bedel, net teslim tarihi ve gecikme için cezai şart içeren yazılı sözleşme.":{"en":"A written contract with a fixed lump-sum price, a clear delivery date and a penal clause for delay.","ru":"Письменный договор с фиксированной твёрдой ценой, чёткой датой сдачи и штрафным условием за просрочку.","zh":"含固定总价包干、明确交付日期与逾期违约条款的书面合同。","ar":"عقد مكتوب بسعر إجمالي مقطوع ثابت وتاريخ تسليم واضح وشرط جزائي على التأخير."},"TBDY 2018 uyumlu mimari-statik-MEP projeler, BIM koordinasyonu ve yapı ruhsatı.":{"en":"TBDY 2018-compliant architectural-structural-MEP designs, BIM coordination and the building permit.","ru":"Соответствующие TBDY 2018 архитектурно-конструктивные-MEP проекты, BIM-координация и разрешение на строительство.","zh":"符合 TBDY 2018 的建筑-结构-机电设计、BIM 协调与建筑许可。","ar":"تصاميم معمارية-إنشائية-MEP متوافقة مع TBDY 2018، وتنسيق BIM ورخصة البناء."},"Denetimli Üretim":{"en":"Inspected Production","ru":"Поднадзорное производство","zh":"受监理生产","ar":"إنتاج مُدقَّق"},"Bağımsız yapı denetimi (4708), kademeli hakediş ve haftalık ilerleme raporu.":{"en":"Independent building inspection (4708), staged progress payments and a weekly progress report.","ru":"Независимый строительный надзор (4708), поэтапные платежи по факту выполнения и еженедельный отчёт о ходе работ.","zh":"独立建筑监理（4708）、分阶段进度款与每周进度报告。","ar":"تدقيق إنشائي مستقل (4708)، دفعات مرحلية وتقرير تقدم أسبوعي."},"Belgeli Teslim":{"en":"Documented Handover","ru":"Документированная сдача","zh":"凭证交付","ar":"تسليم موثّق"},"Enerji kimlik belgesi, iskân, geçici-kesin kabul ve garanti süresi.":{"en":"Energy performance certificate, occupancy permit, provisional-final acceptance and a warranty period.","ru":"Энергетический паспорт, разрешение на ввод в эксплуатацию, предварительная-окончательная приёмка и гарантийный срок.","zh":"能源身份证书、房屋使用许可、初步-最终验收与质保期。","ar":"شهادة هوية الطاقة، رخصة الإشغال، الاستلام المؤقت-النهائي وفترة الضمان."},"Güvenceler & standartlar":{"en":"Guarantees & standards","ru":"Гарантии и стандарты","zh":"保障与标准","ar":"الضمانات والمعايير"},"Her iddiamız bir standarda, sertifikaya veya ölçülebilir taahhüde dayanır. Sözü kanıta bağlarız.":{"en":"Every claim we make rests on a standard, a certificate or a measurable commitment. We tie our word to proof.","ru":"Каждое наше утверждение опирается на стандарт, сертификат или измеримое обязательство. Слово мы подкрепляем доказательством.","zh":"我们的每一项主张都基于标准、认证或可衡量的承诺。我们以证据兑现承诺。","ar":"يستند كل ادعاء لنا إلى معيار أو شهادة أو التزام قابل للقياس. نربط كلمتنا بالدليل."},"Deprem":{"en":"Earthquake","ru":"Землетрясение","zh":"地震","ar":"الزلازل"},"TBDY 2018 & zemin etüdü":{"en":"TBDY 2018 & soil survey","ru":"TBDY 2018 и изыскания грунта","zh":"TBDY 2018 与地质勘察","ar":"TBDY 2018 ومسح التربة"},"Tüm taşıyıcı sistemler güncel deprem yönetmeliğine, zemin sınıfına uygun deprem tasarım sınıfı ve performans hedefiyle boyutlandırılır.":{"en":"All structural systems are designed to the current seismic code, with a seismic design class and performance target appropriate to the soil class.","ru":"Все несущие системы рассчитываются по действующим сейсмическим нормам, с классом сейсмического проектирования и целевыми характеристиками, соответствующими классу грунта.","zh":"所有承重体系均按现行抗震规范，以符合土壤类别的抗震设计等级与性能目标进行设计。","ar":"تُصمَّم جميع الأنظمة الإنشائية وفق كود الزلازل الساري، بصنف تصميم زلزالي وهدف أداء ملائمين لصنف التربة."},"Denetim":{"en":"Inspection","ru":"Надзор","zh":"监理","ar":"التدقيق"},"Bağımsız yapı denetimi (4708)":{"en":"Independent building inspection (4708)","ru":"Независимый строительный надзор (4708)","zh":"独立建筑监理（4708）","ar":"تدقيق إنشائي مستقل (4708)"},"Her etap, 4708 sayılı kanun kapsamında bağımsız yapı denetim kuruluşu ve kendi kalite kontrolümüzle belgelenir.":{"en":"Every stage is documented under Law No. 4708 by an independent building-inspection body and our own quality control.","ru":"Каждый этап документируется в рамках Закона № 4708 независимой организацией строительного надзора и нашим собственным контролем качества.","zh":"每个阶段均在第 4708 号法律框架下，由独立建筑监理机构与我们自有的质量控制加以记录。","ar":"يُوثَّق كل مرحلة في إطار القانون رقم 4708 بواسطة جهة تدقيق إنشائي مستقلة ورقابة الجودة الخاصة بنا."},"İş Güvenliği":{"en":"Occupational Safety","ru":"Техника безопасности","zh":"职业安全","ar":"السلامة المهنية"},"ISO 45001 & 6331":{"en":"ISO 45001 & 6331","ru":"ISO 45001 и 6331","zh":"ISO 45001 与 6331","ar":"ISO 45001 و 6331"},"Sertifikalı İSG yönetim sistemi, düzenli saha eğitimleri ve sıfır kaza hedefiyle çalışan güvenliğini önceliklendiririz.":{"en":"With a certified OHS management system, regular field training and a zero-accident target, we prioritise worker safety.","ru":"С сертифицированной системой управления охраной труда, регулярным обучением на площадке и целью нулевого травматизма мы ставим безопасность работников в приоритет.","zh":"凭借经认证的职业安全管理体系、定期现场培训与零事故目标，我们将工人安全置于首位。","ar":"بنظام إدارة سلامة مهنية معتمد وتدريبات ميدانية منتظمة وهدف صفر حوادث، نضع سلامة العاملين في المقدمة."},"Kalite":{"en":"Quality","ru":"Качество","zh":"质量","ar":"الجودة"},"ISO 9001 & 14001":{"en":"ISO 9001 & 14001","ru":"ISO 9001 и 14001","zh":"ISO 9001 与 14001","ar":"ISO 9001 و 14001"},"Entegre kalite ve çevre yönetim sistemi; enerji verimli tasarım ve düşük karbonlu üretim.":{"en":"An integrated quality and environmental management system; energy-efficient design and low-carbon production.","ru":"Интегрированная система управления качеством и окружающей средой; энергоэффективное проектирование и низкоуглеродное производство.","zh":"一体化的质量与环境管理体系；节能设计与低碳生产。","ar":"نظام متكامل لإدارة الجودة والبيئة؛ تصميم موفّر للطاقة وإنتاج منخفض الكربون."},"Sabit fiyat & cezai şart":{"en":"Fixed price & penal clause","ru":"Фиксированная цена и штрафное условие","zh":"固定价格与违约条款","ar":"سعر ثابت وشرط جزائي"},"Götürü bedel sözleşmesi, net teslim tarihi ve gecikmeye karşı cezai şartla süreç öngörülebilir kılınır.":{"en":"With a lump-sum contract, a clear delivery date and a penal clause against delay, the process is made predictable.","ru":"Твёрдым договором, чёткой датой сдачи и штрафным условием против просрочки процесс делается предсказуемым.","zh":"以总价包干合同、明确交付日期与针对逾期的违约条款，使流程可预见。","ar":"بعقد بسعر مقطوع وتاريخ تسليم واضح وشرط جزائي ضد التأخير، يُجعل المسار قابلًا للتنبؤ."},"Veri":{"en":"Data","ru":"Данные","zh":"数据","ar":"البيانات"},"Bölge zekası & değer analizi":{"en":"Regional intelligence & value analysis","ru":"Региональная аналитика и анализ стоимости","zh":"区域情报与价值分析","ar":"الذكاء الإقليمي وتحليل القيمة"},"Her projeyi mahalle bazlı fiyat endeksi, 5 yıllık değer trendi, yatırım skoru ve deprem/fay analiziyle sunarız.":{"en":"We present every project with a neighbourhood-level price index, a 5-year value trend, an investment score and earthquake/fault analysis.","ru":"Каждый проект мы представляем с индексом цен на уровне района, 5-летним трендом стоимости, инвестиционной оценкой и анализом сейсмики/разломов.","zh":"我们以街区级价格指数、5 年价值趋势、投资评分与地震/断层分析呈现每个项目。","ar":"نعرض كل مشروع بمؤشر أسعار على مستوى الحي، واتجاه قيمة على مدى 5 سنوات، ودرجة استثمار، وتحليل زلازل/صدوع."},"Sık sorulan sorular":{"en":"Frequently asked questions","ru":"Часто задаваемые вопросы","zh":"常见问题","ar":"الأسئلة الشائعة"},"Konut, kentsel dönüşüm, kat karşılığı, tadilat, güçlendirme ve ticari yapılar hakkında en çok merak edilenler.":{"en":"The most common questions about residential, urban-renewal, land-for-flat, renovation, retrofitting and commercial buildings.","ru":"Самые частые вопросы о жилье, городской реновации, строительстве в обмен на квартиры, ремонте, усилении и коммерческих зданиях.","zh":"关于住宅、城市更新、以房换地、翻新、加固与商业建筑最受关注的问题。","ar":"أكثر ما يُسأل عنه حول المساكن والتحول الحضري والإنشاء مقابل حصص شقق والتجديد والتقوية والمباني التجارية."},"Konut inşaatı metrekare maliyeti 2026'da ne kadar?":{"en":"What is the per-square-metre cost of residential construction in 2026?","ru":"Сколько стоит квадратный метр жилищного строительства в 2026 году?","zh":"2026 年住宅建筑的每平方米造价是多少？","ar":"كم تبلغ تكلفة المتر المربع للإنشاء السكني في 2026؟"},"Maliyet; zemin sınıfı, kat adedi, malzeme ve cephe sistemine göre değişir. Sağlıklı rakam yerinde keşif ve metraj sonrası verilir — bu yüzden sabit fiyat yerine güncel keşifle şeffaf teklif sunuyoruz.":{"en":"The cost varies with the soil class, number of floors, materials and façade system. A sound figure is given after an on-site survey and quantity take-off — which is why we offer a transparent quote based on a current survey rather than a fixed price.","ru":"Стоимость зависит от класса грунта, этажности, материалов и фасадной системы. Достоверная цифра называется после осмотра на месте и обмеров — поэтому вместо фиксированной цены мы предлагаем прозрачное предложение на основе актуального осмотра.","zh":"造价随土壤类别、层数、材料与立面体系而变化。稳妥的数字在现场勘察与工程量计算后给出——因此我们提供基于当前勘察的透明报价，而非固定价格。","ar":"تتغير التكلفة بحسب صنف التربة وعدد الطوابق والمواد ونظام الواجهة. ويُعطى الرقم الموثوق بعد المعاينة الميدانية وحساب الكميات — لذلك نقدّم عرضًا شفافًا مبنيًا على معاينة راهنة بدلًا من سعر ثابت."},"Binam deprem yönetmeliğine uygun olacak mı?":{"en":"Will my building comply with the seismic code?","ru":"Будет ли моё здание соответствовать сейсмическим нормам?","zh":"我的建筑会符合抗震规范吗？","ar":"هل سيكون مبناي متوافقًا مع كود الزلازل؟"},"Evet. Tüm projelerimiz TBDY 2018'e göre, zemin sınıfına uygun deprem tasarım sınıfı ve performans hedefiyle boyutlandırılır ve bağımsız yapı denetim kuruluşunca denetlenir.":{"en":"Yes. All our projects are designed to TBDY 2018, with a seismic design class and performance target appropriate to the soil class, and are inspected by an independent building-inspection body.","ru":"Да. Все наши проекты рассчитываются по TBDY 2018, с классом сейсмического проектирования и целевыми характеристиками, соответствующими классу грунта, и проверяются независимой организацией строительного надзора.","zh":"会。我们所有项目均按 TBDY 2018、以符合土壤类别的抗震设计等级与性能目标进行设计，并由独立建筑监理机构检验。","ar":"نعم. تُصمَّم جميع مشاريعنا وفق TBDY 2018، بصنف تصميم زلزالي وهدف أداء ملائمين لصنف التربة، وتُدقَّق من جهة تدقيق إنشائي مستقلة."},"Kentsel dönüşümde cebimden para çıkar mı?":{"en":"Will urban renewal cost me out of pocket?","ru":"Придётся ли мне платить из своего кармана при городской реновации?","zh":"城市更新会让我自掏腰包吗？","ar":"هل سأدفع من جيبي في التحول الحضري؟"},"Kat karşılığı modelinde arsa sahibi para ödemez; ayrıca kira yardımı, düşük faizli kredi ve vergi muafiyeti gibi devlet destekleri devreye girer.":{"en":"In the land-for-flat model the landowner pays nothing; in addition, government supports such as rent assistance, low-interest loans and tax exemptions come into play.","ru":"В модели в обмен на квартиры владелец земли не платит; кроме того, вступают в действие государственные меры поддержки, такие как арендная помощь, льготные кредиты и налоговые льготы.","zh":"在以房换地模式中，土地所有者无需付款；此外还会启用租金补助、低息贷款与税收减免等政府支持。","ar":"في نموذج الإنشاء مقابل حصص شقق لا يدفع مالك الأرض؛ كما تدخل حيّز التنفيذ أشكال دعم حكومي مثل مساعدة الإيجار والقروض منخفضة الفائدة والإعفاءات الضريبية."},"Komşularımın hepsi imza atmazsa kentsel dönüşüm olur mu?":{"en":"Can urban renewal go ahead if not all my neighbours sign?","ru":"Возможна ли городская реновация, если не все мои соседи подпишут?","zh":"如果邻居没有全部签字，城市更新还能进行吗？","ar":"هل يتم التحول الحضري إذا لم يوقّع جميع جيراني؟"},"Karar arsa payının 2/3 çoğunluğuyla alınır. Katılmayan maliklerin payı, bağımsız (SPK lisanslı) değerleme rayici üzerinden açık artırmayla değerlendirilir.":{"en":"The decision is taken by a two-thirds majority of the land share. The share of non-participating owners is valued and sold by auction at the appraised market rate of an independent (CMB-licensed) valuer.","ru":"Решение принимается большинством 2/3 долей участка. Доля не участвующих собственников оценивается и реализуется с аукциона по рыночной стоимости, определённой независимым (лицензированным SPK) оценщиком.","zh":"决定以地块份额 2/3 多数作出。未参与业主的份额按独立（SPK 持牌）估价机构评定的市场行情通过拍卖处置。","ar":"يُتَّخذ القرار بأغلبية ثلثي حصص الأرض. أما حصة المُلّاك غير المشاركين فتُقيَّم وتُباع بالمزاد وفق القيمة السوقية التي تحددها جهة تقييم مستقلة (مرخّصة من SPK)."},"Kat karşılığında hiç para öder miyim?":{"en":"Do I pay anything at all in land-for-flat?","ru":"Плачу ли я вообще что-нибудь при строительстве в обмен на квартиры?","zh":"以房换地中我需要付任何钱吗？","ar":"هل أدفع أي مبلغ في الإنشاء مقابل حصص شقق؟"},"Hayır. Kat karşılığı modelinde para ödemez, arsa payı devredersiniz; karşılığında sözleşmede net yazılı bağımsız bölümleri alırsınız. Güvence teminat ipoteği ve cezai şartla sağlanır.":{"en":"No. In the land-for-flat model you pay no money but transfer a land share; in return you receive the units clearly written in the contract. Security is provided through a security mortgage and a penal clause.","ru":"Нет. В модели в обмен на квартиры вы не платите денег, а передаёте долю участка; взамен получаете самостоятельные помещения, чётко прописанные в договоре. Обеспечение предоставляется обеспечительной ипотекой и штрафным условием.","zh":"不需要。在以房换地模式中，您无需付款，而是转让地块份额；作为回报，您获得合同中明确写明的独立单元。担保通过担保抵押与违约条款提供。","ar":"لا. في نموذج الإنشاء مقابل حصص شقق لا تدفع مالًا بل تنقل حصة من الأرض؛ وتحصل في المقابل على الوحدات المستقلة المكتوبة بوضوح في العقد. ويُؤمَّن الضمان برهن ضمان وشرط جزائي."},"Tadilat için ruhsat gerekli mi?":{"en":"Is a permit required for renovation?","ru":"Требуется ли разрешение на ремонт?","zh":"翻新需要许可吗？","ar":"هل يلزم ترخيص للتجديد؟"},"Boya, zemin ve dolap gibi işler ruhsatsız yapılabilir; duvar kaldırma, ıslak hacim taşıma ve tesisat değişikliği için belediye tadilat ruhsatı gerekir. Taşıyıcı sisteme yalnızca statik mühendis onayıyla dokunulur.":{"en":"Work such as painting, flooring and cabinetry can be done without a permit; removing a wall, relocating a wet area and altering the plumbing require a municipal renovation permit. The structural system is touched only with a structural engineer's approval.","ru":"Такие работы, как покраска, полы и шкафы, можно выполнять без разрешения; для сноса стены, переноса мокрой зоны и изменения инженерных сетей требуется муниципальное разрешение на ремонт. К несущей системе прикасаются только с согласования инженера-конструктора.","zh":"涂料、地面与橱柜等工作可无许可进行；拆墙、移动湿区与改动管线则需要市政翻新许可。承重体系仅在结构工程师批准下方可触动。","ar":"يمكن تنفيذ أعمال كالدهان والأرضيات والخزائن دون ترخيص؛ أما إزالة جدار ونقل منطقة رطبة وتعديل التمديدات فتتطلب رخصة تجديد من البلدية. ولا يُمسّ النظام الإنشائي إلا بموافقة مهندس إنشائي."},"Anahtar teslim ne demek, fiyat sabit mi kalır?":{"en":"What does turnkey mean, and does the price stay fixed?","ru":"Что означает «под ключ» и остаётся ли цена фиксированной?","zh":"交钥匙是什么意思，价格会保持固定吗？","ar":"ماذا يعني التسليم المفتاح، وهل يبقى السعر ثابتًا؟"},"Proje, ruhsat, tedarik ve inşaatın tümünün tek yüklenicide olduğu modeldir. Sözleşmedeki götürü bedel sabittir; kapsam dışı ek talepler ayrıca ve yazılı olarak fiyatlandırılır.":{"en":"It is the model in which the design, permit, procurement and construction are all with a single contractor. The lump-sum price in the contract is fixed; additional requests outside the scope are priced separately and in writing.","ru":"Это модель, при которой проект, разрешение, поставки и строительство целиком у единственного подрядчика. Твёрдая цена в договоре фиксированная; дополнительные запросы вне объёма расцениваются отдельно и в письменной форме.","zh":"这是一种设计、许可、采购与施工全部由单一承包商承担的模式。合同中的总价包干是固定的；范围之外的额外要求另行并以书面形式计价。","ar":"هو النموذج الذي يكون فيه التصميم والرخصة والتوريد والإنشاء كلها لدى مقاول واحد. والسعر المقطوع في العقد ثابت؛ أما الطلبات الإضافية خارج النطاق فتُسعَّر على حدة وكتابةً."},"Güçlendirme mi, yıkıp yeniden yapmak mı daha doğru?":{"en":"Is retrofitting or demolish-and-rebuild the better choice?","ru":"Что правильнее — усиление или снос и строительство заново?","zh":"加固还是拆除重建更合适？","ar":"أيّهما أصح: التقوية أم الهدم وإعادة البناء؟"},"Karar maliyet ve imar hakkına bağlıdır. Güçlendirme maliyeti yeniden yapımın %40'ını aşıyorsa yeniden yapım; imar hakkı (kat/metrekare) kaybı istenmiyorsa güçlendirme öne çıkar. İki senaryoyu bağımsız mühendis raporuyla karşılaştırmalı sunarız.":{"en":"The decision depends on cost and zoning rights. If the retrofitting cost exceeds 40% of rebuilding, rebuilding is preferred; if a loss of zoning rights (floors/square metres) is not acceptable, retrofitting comes to the fore. We present the two scenarios comparatively with an independent engineer's report.","ru":"Решение зависит от стоимости и прав застройки. Если стоимость усиления превышает 40% стоимости нового строительства, предпочтительно новое строительство; если потеря прав застройки (этажи/квадратные метры) нежелательна, на первый план выходит усиление. Мы представляем оба сценария сравнительно, с отчётом независимого инженера.","zh":"决定取决于成本与建筑权利。若加固成本超过重建的 40%，则重建更可取；若不希望损失建筑权利（层数/平方米），则加固更为突出。我们以独立工程师报告对两种方案进行对比呈现。","ar":"يعتمد القرار على التكلفة وحقوق البناء. إذا تجاوزت تكلفة التقوية 40% من إعادة البناء، فإعادة البناء أفضل؛ وإذا كان فقدان حقوق البناء (طوابق/أمتار مربعة) غير مقبول، تتقدّم التقوية. ونعرض السيناريوهين على نحو مقارن بتقرير مهندس مستقل."},"Ticari yapıda hangi ruhsat ve onaylar gerekir?":{"en":"Which permits and approvals are required for a commercial building?","ru":"Какие разрешения и согласования требуются для коммерческого здания?","zh":"商业建筑需要哪些许可与批准？","ar":"ما الرخص والموافقات اللازمة للمبنى التجاري؟"},"Yapı ruhsatı, yangın onayı (BYKHY), otopark uygunluğu ve işletme için işyeri açma ve çalışma ruhsatı gerekir; tasarımı baştan bu uyumla kurarız. LEED/BREEAM sertifikası opsiyoneldir.":{"en":"A building permit, fire approval (BYKHY), parking compliance and, for operation, a business opening and operating licence are required; we set up the design with this compliance from the start. LEED/BREEAM certification is optional.","ru":"Требуются разрешение на строительство, пожарное согласование (BYKHY), соответствие по парковке и для эксплуатации — разрешение на открытие и работу предприятия; проект мы изначально выстраиваем с этим соответствием. Сертификация LEED/BREEAM опциональна.","zh":"需要建筑许可、消防批准（BYKHY）、停车合规，以及经营所需的营业开办与经营许可；我们从一开始便以此合规搭建设计。LEED/BREEAM 认证为可选项。","ar":"يلزم رخصة بناء، وموافقة حريق (BYKHY)، وتوافق المواقف، وللتشغيل رخصة فتح وتشغيل المنشأة؛ ونبني التصميم على هذا التوافق منذ البداية. واعتماد LEED/BREEAM اختياري."},"İnşaat süreci ne kadar sürer?":{"en":"How long does the construction process take?","ru":"Сколько длится процесс строительства?","zh":"建筑流程需要多长时间？","ar":"كم تستغرق عملية الإنشاء؟"},"Proje-ruhsat aşaması genelde 2-6 ay; inşaat, ölçek ve kat adedine göre planlanır. Sözleşmede net teslim tarihi ve gecikme için cezai şart yer alır. Komple daire tadilatı yaklaşık 5-8 hafta sürer.":{"en":"The design-permit stage generally takes 2-6 months; construction is planned according to scale and number of floors. The contract includes a clear delivery date and a penal clause for delay. A complete flat renovation takes roughly 5-8 weeks.","ru":"Этап проектирования-разрешения обычно занимает 2-6 месяцев; строительство планируется в зависимости от масштаба и этажности. В договоре указаны чёткая дата сдачи и штрафное условие за просрочку. Комплексный ремонт квартиры занимает примерно 5-8 недель.","zh":"设计-许可阶段通常需 2-6 个月；施工按规模与层数规划。合同中列有明确交付日期与逾期违约条款。公寓整体翻新约需 5-8 周。","ar":"تستغرق مرحلة التصميم-الرخصة عادةً 2-6 أشهر؛ ويُخطَّط الإنشاء بحسب الحجم وعدد الطوابق. ويتضمّن العقد تاريخ تسليم واضحًا وشرطًا جزائيًا على التأخير. ويستغرق التجديد الشامل للشقة نحو 5-8 أسابيع."},"İletişim":{"en":"Contact","ru":"Контакты","zh":"联系我们","ar":"التواصل"},"Projenizi birliktehayata geçirelim":{"en":"Let's bring your project<br>to life together","ru":"Воплотим ваш проект в жизнь вместе","zh":"让我们携手将您的项目变为现实","ar":"لنحقق مشروعك معًا"},"Ücretsiz Keşif & Teklif →":{"en":"Free Survey & Quote →","ru":"Бесплатный выезд и предложение →","zh":"免费勘察与报价 →","ar":"معاينة وعرض مجانيان →"}};
